constexpr int kPillSeparatorFont = 40;
// A glow that fades while it lasts (1 at the start, a little pulse in it;
// 0 before and after): the pill's lines after one was added in the
// settings (g_separatorGlowAt, when; 0 never), and the settings' own chips.
float GlowAmount(double now, double at, double seconds) {
    const double t = now - at;
    if (at <= 0 || t < 0 || t >= seconds) {
        return 0;
    }
    return (float)((1 - t / seconds) * (0.6 + 0.4 * std::sin(t * 8)));
}
constexpr double kSeparatorGlowSeconds = 1.6;
double g_separatorGlowAt = 0;
float SeparatorGlow() {
    return GlowAmount(NowSeconds(), g_separatorGlowAt,
                      kSeparatorGlowSeconds);
}
// (Still drawn a moment after it ends, once more without it.)
bool SeparatorGlowActive() {
    return g_separatorGlowAt > 0 &&
           NowSeconds() - g_separatorGlowAt < kSeparatorGlowSeconds + 0.1;
}
