// Island::StepVisualizer).
constexpr double kVizStepSeconds = 1.0 / 30;
// The bars drawn at most this often (see Island::StepVisualizer): a hair
// under a 60th, like kWindowFrameSeconds, so that every frame of a 60 Hz
// screen, a little early, passes (exactly a 60th kept them at 30).
constexpr double kVizFrameSeconds = 0.0125;
// A meter's peak at most this low is silence.
constexpr float kVizSilentPeak = 0.001f;
// Its seven bars (an odd count: one in the middle), the middle one the
// tallest; the sound reaches each one this many readings after the one
// inside it (from the middle out), so the levels of the last readings are
// kept. Each one also sways a little, two waves at its own speed (radians a
// second, none a multiple of another, so they never move together).
constexpr size_t kVizBars = 7;
constexpr float kVizShape[kVizBars] = {0.5f,  0.73f, 0.93f, 1.0f,
                                       0.93f, 0.73f, 0.5f};
constexpr float kVizSpeeds[kVizBars] = {4.3f, 5.9f, 3.7f, 6.4f,
                                        4.9f, 5.3f, 4.6f};
constexpr size_t kVizLagReadings = 2;
constexpr size_t kVizHistory = kVizBars / 2 * kVizLagReadings + 1;
// The bars' width, the room between them and their highest, at an icon
// scale, as chosen (islandVizWidth, islandVizSpacing, islandVizHeight);
// how wide they are together.
struct VizBarsLook {
    float bar;
    float gap;
    float most;
    float total;
};
VizBarsLook VizLook(float iconScale) {
    VizBarsLook look;
    look.bar = std::max(
        2.0f, std::round(2.5f * iconScale * g_settings.islandVizWidth / 100));
    look.gap = std::max(
        1.0f,
        std::round(1.5f * iconScale * g_settings.islandVizSpacing / 100));
    look.most = std::round(15 * iconScale * g_settings.islandVizHeight / 100);
    look.total = kVizBars * look.bar + (kVizBars - 1) * look.gap;
    return look;
}
// What's playing on the minimized line (islandMusicLine, #7045): instead of
// the line, a thin pill with the song's cover and the visualizer's bars (a
// smaller look of them), a little thicker than the line, like macOS's
// compact "Now Playing". It shows hidden (minimized, or the Bar hidden into
// its clock's pill), not upright (no room across), while something plays or
// stopped less than kMusicLineGrace ago (a pause, the next song coming).
constexpr float kMusicLineThickness = 18;
constexpr float kMusicLineCover = 12;
constexpr float kMusicLineBarsScale = 0.75f;
constexpr double kMusicLineGrace = 3;
// What plays there: what's playing plays and, with apps chosen for the
// visualizer (VizApps, #7343), one of them is heard, like the pill's
// visualizer item.
bool MusicLinePlays(bool mediaPlaying, bool appsChosen, bool appHeard) {
    return mediaPlaying && (!appsChosen || appHeard);
}
bool MusicLineShows(bool on,
                    bool hidden,
                    bool upright,
                    bool present,
                    bool playing,
                    double sinceStopped) {
    return on && hidden && !upright && present &&
           (playing || sinceStopped < kMusicLineGrace);
}

// Its cover and bars side by side (the bars `barsWidth` wide).
float MusicLineContent(float barsWidth, float scale) {
    return std::round((kMusicLineCover + 6) * scale) + barsWidth;
}

// Alone on the line: centered on it with room around the cover and bars,
// against the line's edge (`edgeY`, the window's top or bottom) and as far
// past it as it's thick, so only its far corners show rounded (like the
// clock's pill against the edge, islandHideClockEdge).
D2D1_RECT_F MusicLineRect(float centerX,
                          float edgeY,
                          float barsWidth,
                          float scale) {
    const float width =
        MusicLineContent(barsWidth, scale) + std::round(20 * scale);
    const float thin = std::round(kMusicLineThickness * scale);
    return {centerX - width / 2, edgeY - thin, centerX + width / 2,
            edgeY + thin};
}

