// `look` a share `t` of the way to `to`.
void PetBlend(PetLookParams& look, const PetLookParams& to, float t) {
    look.glow += (to.glow - look.glow) * t;
    look.size += (to.size - look.size) * t;
    look.y += (to.y - look.y) * t;
    look.open += (to.open - look.open) * t;
    look.slant += (to.slant - look.slant) * t;
    look.happy += (to.happy - look.happy) * t;
    look.sat += (to.sat - look.sat) * t;
    look.cool += (to.cool - look.cool) * t;
    look.warm += (to.warm - look.warm) * t;
    look.lid += (to.lid - look.lid) * t;
    look.red += (to.red - look.red) * t;
    look.squeeze += (to.squeeze - look.squeeze) * t;
    look.wide += (to.wide - look.wide) * t;
}

bool PetLookNear(const PetLookParams& a, const PetLookParams& b) {
    constexpr float kNear = 0.004f;
    return std::fabs(a.glow - b.glow) < kNear &&
           std::fabs(a.size - b.size) < kNear &&
           std::fabs(a.y - b.y) < kNear && std::fabs(a.open - b.open) < kNear &&
           std::fabs(a.slant - b.slant) < kNear &&
           std::fabs(a.happy - b.happy) < kNear &&
           std::fabs(a.sat - b.sat) < kNear &&
           std::fabs(a.cool - b.cool) < kNear &&
           std::fabs(a.warm - b.warm) < kNear &&
           std::fabs(a.lid - b.lid) < kNear &&
           std::fabs(a.red - b.red) < kNear &&
           std::fabs(a.squeeze - b.squeeze) < kNear &&
           std::fabs(a.wide - b.wide) < kNear;
}

// A feeling over the mood for a moment (see PetAnim::Emote): its look takes
// over the mood's for the values it says, blending in and out like the
// moods, with a motion of its own (see DrawPetFaisca).
enum class PetEmotion {
    Smile,
    Giggle,
    Proud,
    Angry,
    Frustrated,
    Startled,
    Sad,
    Yawn,
    Sneeze,
    Curious,
    Bliss
};
constexpr int kPetEmotions = (int)PetEmotion::Bliss + 1;
// How long each one lasts by itself (seconds).
constexpr double kPetEmotionLife[kPetEmotions] = {1.3, 1.2, 1.8, 2.2,
                                                  2,   0.9, 2.4, 1.6,
                                                  1.2, 1.8, 2.4};

// The values a feeling sets over the mood's look.
void PetEmotionLook(PetLookParams& look, PetEmotion emotion) {
    switch (emotion) {
        case PetEmotion::Smile:
        case PetEmotion::Giggle:
            look.happy = 1;
            break;
        case PetEmotion::Proud:
            look.happy = 1;
            look.glow = 1.25f;
            look.size = 1.06f;
            break;
        case PetEmotion::Angry:
            look.slant = 0.9f;
            look.lid = 0.32f;
            look.open = 1;
            look.red = 0.6f;
            look.glow = 1;
            break;
        case PetEmotion::Frustrated:
            look.squeeze = 1;
            look.open = 0.45f;
            look.slant = 0.25f;
            look.sat = 0.15f;
            break;
        case PetEmotion::Startled:
            look.wide = 1;
            look.open = 1.2f;
            look.lid = 0;
            look.glow = 1.1f;
            break;
        case PetEmotion::Sad:
            look.slant = -0.55f;
            look.lid = 0.22f;
            look.open = 0.85f;
            look.cool = 0.4f;
            break;
        case PetEmotion::Yawn:
            look.open = 0.14f;
            look.lid = 0.4f;
            break;
        case PetEmotion::Sneeze:
            look.squeeze = 0.6f;
            look.open = 0.3f;
            break;
        case PetEmotion::Curious:
            look.wide = 0.45f;
            look.open = 1.08f;
            look.slant = -0.1f;
            break;
        case PetEmotion::Bliss:
            look.happy = 1;
            look.glow = 1.15f;
            look.red = 0.15f;
            break;
    }
}

