// Whether she reacts to it (a PetReaction, or kPetReactNotify): only while
// she reacts to the PC (islandPetReacts), to all of it
// (islandPetReactAll) or to that one (its own switch, shown with "All
// reactions" off; copying and moving files share one).
bool PetReactionOn(int which) {
    if (!g_settings.islandPetReacts) {
        return false;
    }
    if (g_settings.islandPetReactAll) {
        return true;
    }
    switch (which) {
        case (int)PetReaction::FileCopy:
        case (int)PetReaction::FileMove:
            return g_settings.islandPetReactFiles;
        case (int)PetReaction::Download:
            return g_settings.islandPetReactDownload;
        case (int)PetReaction::Screenshot:
            return g_settings.islandPetReactScreenshot;
        case (int)PetReaction::Volume:
            return g_settings.islandPetReactVolume;
        case (int)PetReaction::Usb:
            return g_settings.islandPetReactUsb;
        case (int)PetReaction::Charger:
            return g_settings.islandPetReactCharger;
        case (int)PetReaction::WifiDown:
            return g_settings.islandPetReactWifiDown;
        case (int)PetReaction::WifiUp:
            return g_settings.islandPetReactWifiUp;
        case (int)PetReaction::Song:
            return g_settings.islandPetReactSong;
        case (int)PetReaction::PomodoroDone:
            return g_settings.islandPetReactPomodoro;
        case (int)PetReaction::Reminder:
            return g_settings.islandPetReactReminder;
        case kPetReactNotify:
            return g_settings.islandPetReactNotify;
        default:
            return false;
    }
}

