// One event of the list: on or off, its source, and its file (a file source).
struct PetSoundSlot {
    bool on = true;
    int source = kPetSourceNative;
    std::wstring path;
};
using PetSoundList = std::array<PetSoundSlot, kPetSounds>;
// The sounds that come by themselves, with nothing done (a yawn, a sneeze,
// waking up startled, a new song, which the volume's reaction uses too):
// off until turned on. The rest on.
constexpr bool PetSoundOnAtFirst(int sound) {
    return sound != (int)PetSound::Yawn && sound != (int)PetSound::Sneeze &&
           sound != (int)PetSound::Startled && sound != (int)PetSound::Song;
}
PetSoundList DefaultPetSoundList() {
    PetSoundList list;
    for (int i = 0; i < kPetSounds; i++) {
        list[i].on = PetSoundOnAtFirst(i);
    }
    return list;
}

constexpr size_t kPetSoundPathMost = 400;
// The list as stored (islandPetSoundList).
constexpr size_t kPetSoundListRoom = 12 * 1024;

// A path in the stored list: ";" and "%" written as %3B and %25.
std::wstring PetSoundPathEscape(const std::wstring& path) {
    std::wstring escaped;
    for (WCHAR c : path) {
        escaped += c == L';' ? std::wstring(L"%3B")
                   : c == L'%' ? std::wstring(L"%25")
                               : std::wstring(1, c);
    }
    return escaped;
}

std::wstring PetSoundPathUnescape(std::wstring_view text) {
    std::wstring plain;
    for (size_t i = 0; i < text.size(); i++) {
        if (text[i] == L'%' && i + 2 < text.size() &&
            text.substr(i + 1, 2) == L"3B") {
            plain += L';';
            i += 2;
        } else if (text[i] == L'%' && i + 2 < text.size() &&
                   text.substr(i + 1, 2) == L"25") {
            plain += L'%';
            i += 2;
        } else {
            plain += text[i];
        }
    }
    return plain;
}

// The list read: "<key>:<0 or 1>:<source>:<path>" separated by ";", only the
// events that aren't as at first (see PetSoundOnAtFirst; a short text for the
// usual). Anything it
// can't read is left out, an event named twice keeps its first line, a number
// out of range is the usual one, and a file source without a file is native.
PetSoundList DecodePetSoundList(std::wstring_view text) {
    PetSoundList list = DefaultPetSoundList();
    std::array<bool, kPetSounds> seen{};
    if (text.size() > kPetSoundListRoom) {
        text = text.substr(0, kPetSoundListRoom);
    }
    size_t start = 0;
    while (start <= text.size()) {
        size_t end = text.find(L';', start);
        if (end == std::wstring_view::npos) {
            end = text.size();
        }
        const std::wstring_view item = text.substr(start, end - start);
        start = end + 1;
        const size_t first = item.find(L':');
        const size_t second = first == std::wstring_view::npos
                                  ? first
                                  : item.find(L':', first + 1);
        const size_t third = second == std::wstring_view::npos
                                 ? second
                                 : item.find(L':', second + 1);
        if (third == std::wstring_view::npos) {
            continue;
        }
        const std::wstring_view key = item.substr(0, first);
        int index = -1;
        for (int i = 0; i < kPetSounds; i++) {
            if (key == kPetSoundInfo[i].key) {
                index = i;
            }
        }
        if (index < 0 || seen[index]) {
            continue;
        }
        seen[index] = true;
        PetSoundSlot& slot = list[index];
        const std::wstring_view on = item.substr(first + 1, second - first - 1);
        slot.on = on != L"0";
        const std::wstring_view source =
            item.substr(second + 1, third - second - 1);
        int number = 0;
        bool digits = !source.empty() && source.size() <= 3;
        for (WCHAR c : source) {
            digits = digits && c >= L'0' && c <= L'9';
            number = number * 10 + (c - L'0');
        }
        slot.source = digits && number < kPetSourcePack + kPetSoundPackCount
                          ? number
                          : kPetSourceNative;
        slot.path = PetSoundPathUnescape(item.substr(third + 1));
        if (slot.path.size() > kPetSoundPathMost) {
            slot.path.clear();
        }
        if (slot.source == kPetSourceFile && slot.path.empty()) {
            slot.source = kPetSourceNative;
        }
        if (slot.source != kPetSourceFile) {
            slot.path.clear();
        }
    }
    return list;
}

std::wstring EncodePetSoundList(const PetSoundList& list) {
    std::wstring text;
    for (int i = 0; i < kPetSounds; i++) {
        const PetSoundSlot& slot = list[i];
        if (slot.on == PetSoundOnAtFirst(i) &&
            slot.source == kPetSourceNative) {
            continue;
        }
        if (!text.empty()) {
            text += L';';
        }
        text += std::wstring(kPetSoundInfo[i].key) + L":" +
                (slot.on ? L"1" : L"0") + L":" +
                std::to_wstring(slot.source) + L":" +
                (slot.source == kPetSourceFile
                     ? PetSoundPathEscape(slot.path)
                     : std::wstring());
    }
    return text;
}

// Whether a sound plays: her sounds and that event on, no full-screen app
// in front, no Do not disturb.
bool PetSoundAllowed(bool master, bool eventOn, bool fullScreen, bool quiet) {
    return master && eventOn && !fullScreen && !quiet;
}

// The volume slider (islandPetSoundVolume, percent).
constexpr int kPetSoundVolumeMin = 0;
constexpr int kPetSoundVolumeMax = 100;
constexpr int kPetSoundVolumeDefault = 60;
constexpr int kPetSoundVolumeStep = 5;

// The volume as a gain.
float PetSoundGain(int volume) {
    return std::clamp(volume, 0, 100) / 100.0f;
}

// Samples: 16 bit, mono, kPetSoundRate.
constexpr int kPetSoundRate = 44100;
using PetPcm = std::vector<int16_t>;
using PetPcmPtr = std::shared_ptr<const PetPcm>;
// A file's sound is cut to this (it is an effect, not a song).
constexpr int kPetSoundSecondsMost = 8;
constexpr size_t kPetSoundFileMost = 32 * 1024 * 1024;

////////////////////////////////////////////////////////////////////////////////
// The synthesis: each sound is a few tones and bursts of noise (kPetTones,
// kPetNoises, from the sound design), all sent a little into a room, then
// trimmed and set to a level. Made once per sound when first needed.

// The room: the seconds it goes on after the last tone, how long it takes to
// fade, how much of it is heard, its level and its brightness.
constexpr double kPetSoundTail = 1.1;
constexpr double kPetRoomSeconds = 1.4;
constexpr float kPetRoomWet = 0.2f;
constexpr float kPetRoomGain = 0.6f;
constexpr float kPetRoomDamp = 0.42f;
// What goes to the room: from the tones and from the noise.
constexpr float kPetSendTone = 0.9f;
constexpr float kPetSendNoise = 0.6f;
// The stored level (the design's sounds, louder), the loudest a sound may
// be, and where the end of a sound is cut (a hair above silence).
constexpr float kPetSoundBoost = 2.4f;
constexpr float kPetSoundPeak = 0.9f;
constexpr float kPetSoundTrim = 2e-4f;

enum class PetOsc : unsigned char { Sine, Triangle, Saw };
// A tone: at `at` s, `dur` s long, a wave at `freq` Hz (sliding to `glide`,
// with a vibrato of `vib` Hz), an envelope of `attack` s then dying away,
// a bell partial of `bell` times its level, through a low-pass at `lp` Hz.
struct PetTone {
    unsigned char sound;
    PetOsc wave;
    float freq;
    float at;
    float dur;
    float vol;
    float attack;
    float glide;
    float bell;
    float lp;
    float vib;
};
// A burst of noise through a band-pass (or high-pass) filter at `freq` Hz
// (sweeping to `sweep`).
struct PetNoise {
    unsigned char sound;
    bool high;
    float at;
    float dur;
    float vol;
    float freq;
    float q;
    float sweep;
};
