const IconInfo* FindIcon(WCHAR glyph) {
    for (const auto& icon : kIcons) {
        if (icon.glyph == glyph) {
            return &icon;
        }
    }
    return nullptr;
}

// The weather's icons (the entries of kIcons from kWeatherGlyphFirst, one
// for each kind of sky, in this order): what the weather draws in the pill
// and its panel when islandWeatherIcons asks for pictures (see WeatherSky).
enum WeatherConcept {
    kSkyClearDay,
    kSkyClearNight,
    kSkyPartlyDay,
    kSkyPartlyNight,
    kSkyCloud,
    kSkyRain,
    kSkyDrizzle,
    kSkySnow,
    kSkySleet,
    kSkyThunder,
    kSkyFog,
    kSkyConcepts
};
constexpr WCHAR kWeatherGlyphFirst = 0xF8E0;

bool IsWeatherIconGlyph(WCHAR glyph) {
    return glyph >= kWeatherGlyphFirst &&
           glyph < kWeatherGlyphFirst + kSkyConcepts;
}

// The kind of sky a weather code (WMO) is, by day or by night: the same
// grouping as the emoji (WeatherEmoji), with freezing rain as sleet.
int WeatherConceptOf(int code, bool day) {
    switch (code) {
        case 0:
            return day ? kSkyClearDay : kSkyClearNight;
        case 1:
            return day ? kSkyPartlyDay : kSkyClearNight;
        case 2:
            return day ? kSkyPartlyDay : kSkyPartlyNight;
        case 3:
            return kSkyCloud;
        case 45:
        case 48:
            return kSkyFog;
        case 51:
        case 53:
        case 55:
            return kSkyDrizzle;
        case 56:
        case 57:
        case 66:
        case 67:
            return kSkySleet;
        case 71:
        case 73:
        case 75:
        case 77:
        case 85:
        case 86:
            return kSkySnow;
        case 95:
        case 96:
        case 99:
            return kSkyThunder;
        default:
            // (Rain, showers, and any code not known.)
            return kSkyRain;
    }
}

WCHAR WeatherGlyphOf(int code, bool day) {
    return (WCHAR)(kWeatherGlyphFirst + WeatherConceptOf(code, day));
}

// A sky as the pill and the weather panel keep it: an emoji, or, when
// pictures are asked for, this mark, the icon's glyph and the emoji drawn if
// there's no picture of it.
constexpr WCHAR kWeatherMark = 1;

bool IsWeatherSky(const std::wstring& sky) {
    return sky.size() >= 2 && sky[0] == kWeatherMark;
}

std::wstring WeatherSkyEmoji(const std::wstring& sky) {
    return IsWeatherSky(sky) ? sky.substr(2) : sky;
}

// Whether the weather's pictures are asked of the icon packs (the one
// chosen, in the Icons tab): their downloads then include them, not before.
std::atomic<bool> g_weatherFromPacks{false};

// The battery's glyph at `percent`: Segoe's ten steps, with the bolt while
// charging. (Charging at 90% is out of the row, E83E: E863, right after
// E862, is the energy saver's battery, #6922.)
WCHAR BatteryGlyphFor(int percent, bool charging) {
    const int tenth = std::clamp((percent + 5) / 10, 0, 10);
    if (tenth >= 10) {
        return charging ? (WCHAR)0xEA93 : (WCHAR)0xE83F;
    }
    if (charging && tenth == 9) {
        return (WCHAR)0xE83E;
    }
    return (WCHAR)((charging ? 0xE85A : 0xE850) + tenth);
}

