// The groups of items on the pill, which can be put in another order in the
// island's settings (the minimize button always ends it).
enum class PillGroup {
    Apps,
    Tray,
    Network,
    Volume,
    Battery,
    Clock,
    Bell,
    Media,
    Power,
    Usage,
    Theme,
    Microphone,
    Notes,
    Tasks,
    Shortcuts,
    Weather,
    Updates,
    Profiles,
    Brightness,
    InputMethod,
    Privacy,
    Drives,
    Desktops,
    // The control center's buttons chosen for the pill, each on its own
    // (see kPillActions): Wi-Fi here, the others after the wallpaper.
    ActionNetwork,
    Folders,
    Wallpaper,
    ActionBluetooth,
    ActionNightLight,
    ActionHotspot,
    ActionAirplane,
    ActionProject,
    ActionCast,
    ActionCaptions,
    ActionAccessibility,
    ActionScreenshot,
    ActionLock,
    ActionEmoji,
    ActionClipboard,
    ActionTaskManager,
    ActionCalculator,
    ActionExplorer,
    ActionKomorebi,
    // komorebi's layout on this monitor, and the app in focus on it.
    KomorebiLayout,
    FocusedApp,
    // (A control center button added later: after the others.)
    ActionShowDesktop,
    // (Items added in 2.1: after the others.)
    NetSpeed,
    WorldClocks,
    Countdown,
    RecycleBin,
    ActionOnScreenKeyboard,
    Timer,
    Visualizer,
    // What's playing's cover and title, and its buttons, each placed on its
    // own (they were part of Media; old orders put them right after it, see
    // DecodePillOrder).
    MediaTitle,
    MediaButtons,
    // The line of the song sung now (see Island::m_lyricsLine).
    Lyrics,
    // (Items added in 3.0: after the others.)
    AiUsage,
    Commands,
    Shelf,
    // (Items added in 3.1: after the others.)
    ActionTouchKeyboard,
    ActionWindowsSettings,
    ActionStartMenuKeys,
    // The apps launcher (see LauncherPanel).
    Launcher,
    // GlazeWM's workspaces on this monitor, a dot each (#7116; after
    // komorebi's layout in the order, see GroupBefore).
    GlazeWorkspaces,
    // Faísca, the pet (after the clock in the order, see GroupBefore;
    // the last of the 64 groups the per-app masks allow).
    Pet,
    Count
};
constexpr int kPillGroups = (int)PillGroup::Count;

// Separators on the pill: a thin line between two groups, put in the order
// with them. Each one in an order is a value past the real groups
// (kPillGroups and its number there, up to kMaxPillSeparators), kept as a '-'
// in the order's text (see EncodePillOrder; the numbers are given again in
// the order they come in). The settings' "+" chip, which adds one, is the
// value after the last.
constexpr int kMaxPillSeparators = 8;
constexpr PillGroup kAddSeparatorChip =
    (PillGroup)(kPillGroups + kMaxPillSeparators);

bool IsPillSeparator(PillGroup group) {
    return (int)group >= kPillGroups &&
           (int)group < kPillGroups + kMaxPillSeparators;
}

bool OrderHasSeparator(const std::vector<PillGroup>& order) {
    return std::any_of(order.begin(), order.end(), IsPillSeparator);
}

// Where the Bar's items split into its two corners (islandBarCorners)
// without the clock in the middle: the left end of the first separator line.
// The items before it go to the left corner, the rest (the clock among them,
// as the order has it) to the right one. -1: no split (the clock in the
// middle splits them, or there is no line).
float BarCornerSplit(const std::vector<IslandSlot>& slots,
                     bool corners,
                     bool clockCentered) {
    if (!corners || clockCentered) {
        return -1;
    }
    for (const auto& slot : slots) {
        if (slot.font == kPillSeparatorFont) {
            return slot.rect.left;
        }
    }
    return -1;
}

// The Bar in three parts (islandBarCorners with two separator lines in the
// order, M27): the groups before the first line go to the left corner, the
// ones between the lines to the middle of the screen (the clock too, when it
// is kept in the middle), the rest to the right corner. With one line the
// Bar splits in two (see BarCornerSplit).
constexpr int kBarParts = 3;

bool BarHasThreeParts(const std::vector<PillGroup>& order, bool corners) {
    return corners &&
           std::count_if(order.begin(), order.end(), IsPillSeparator) >= 2;
}

// The part each group is in: how many lines come before it in the order (the
// third line and the others are inside the last part). The clock kept in the
// middle (`clockCentered`) is in the middle part, wherever the order has it
// (it is laid out among that part's items).
std::array<int, kPillGroups> BarPartOfGroups(
    const std::vector<PillGroup>& order,
    bool clockCentered) {
    std::array<int, kPillGroups> parts{};
    int lines = 0;
    for (const PillGroup group : order) {
        if (IsPillSeparator(group)) {
            lines++;
        } else {
            parts[(int)group] = std::min(lines, kBarParts - 1);
        }
    }
    if (clockCentered) {
        parts[(int)PillGroup::Clock] = 1;
    }
    return parts;
}

// Puts the slots of the Bar's three parts along its `width`: the first
// against the left end, the last against the right one, the middle one in
// the middle of the screen as far as the sides leave room (it never goes over
// them). Only the first `real` slots are items; the ones after are groups
// fading out (see Island::m_groupSwap), which go with the part nearest to
// them. The first line of the second part and of the third isn't drawn: the
// gap is the split.
void PlaceBarParts(std::vector<IslandSlot>& slots,
                   size_t real,
                   const std::array<int, kPillGroups>& parts,
                   float width,
                   float padding) {
    const float none = std::numeric_limits<float>::max();
    float from[kBarParts] = {none, none, none};
    float to[kBarParts] = {-none, -none, -none};
    bool started[kBarParts] = {true, false, false};
    std::vector<int> part(slots.size(), 0);
    int last = 0;
    for (size_t i = 0; i < slots.size() && i < real; i++) {
        IslandSlot& slot = slots[i];
        if (slot.group >= 0 && slot.group < kPillGroups) {
            last = parts[slot.group];
        }
        part[i] = last;
        if (slot.font != kPillSeparatorFont) {
            from[last] = std::min(from[last], slot.rect.left);
            to[last] = std::max(to[last], slot.rect.right);
        } else if (!started[last]) {
            started[last] = true;
            slot.scale = 0;
        }
    }
    for (size_t i = real; i < slots.size(); i++) {
        IslandSlot& slot = slots[i];
        if (slot.font == kPillSeparatorFont) {
            slot.scale = 0;
            continue;
        }
        const float middle = (slot.rect.left + slot.rect.right) / 2;
        float nearest = none;
        for (int p = 0; p < kBarParts; p++) {
            if (from[p] > to[p]) {
                continue;
            }
            const float away = middle < from[p] ? from[p] - middle
                               : middle > to[p]  ? middle - to[p]
                                                 : 0;
            if (away < nearest) {
                nearest = away;
                part[i] = p;
            }
        }
    }
    const auto has = [&](int p) { return from[p] <= to[p]; };
    float shift[kBarParts] = {padding, 0, 0};
    if (has(2)) {
        shift[2] = width - padding - to[2];
    }
    if (has(1)) {
        // Between the sides (they keep the gaps they were laid out with).
        const float least = has(0) ? shift[0] : padding - from[1];
        const float most = has(2) ? shift[2] : width - padding - to[1];
        shift[1] = std::clamp(std::round(width / 2 - (from[1] + to[1]) / 2),
                              least, std::max(least, most));
    }
    for (size_t i = 0; i < slots.size(); i++) {
        slots[i].rect.left += shift[part[i]];
        slots[i].rect.right += shift[part[i]];
    }
}

