// Whether any of the processor (use and temperature), memory, video
// memory, GPU use and GPU temperature items is shown (the usage group has
// a switch for each).
bool AnyUsageShown() {
    return g_settings.usageCpu || g_settings.usageRam ||
           g_settings.usageVram || g_settings.usageGpu ||
           g_settings.usageGpuTemp || g_settings.usageCpuTemp;
}

int GetIslandPref(IslandPref pref);
int PillGroupPref(PillGroup group);

// Whether a group is on the pill (for all apps): its option on, or always.
bool PillGroupOn(PillGroup group) {
    const int pref = PillGroupPref(group);
    if (pref >= 0) {
        return GetIslandPref((IslandPref)pref) != 0;
    }
    return group != PillGroup::Usage || AnyUsageShown();
}

