// A control center button's page in Windows' Settings, opened by its right
// click on the pill (like Windows' quick settings' "Go to Settings"), or
// null: the shortcuts have none (their right click shows the settings
// bubble, as anywhere on the pill).
PCWSTR PillActionPage(ControlId id) {
    switch (id) {
        case ControlId::Network:
            return L"ms-settings:network";
        case ControlId::Bluetooth:
            return L"ms-settings:bluetooth";
        case ControlId::NightLight:
            return L"ms-settings:nightlight";
        case ControlId::Hotspot:
            return L"ms-settings:network-mobilehotspot";
        case ControlId::Airplane:
            return L"ms-settings:network-airplanemode";
        case ControlId::Project:
        case ControlId::Cast:
            return L"ms-settings:display";
        case ControlId::Captions:
            return L"ms-settings:easeofaccess-closedcaptioning";
        case ControlId::Accessibility:
            return L"ms-settings:easeofaccess";
        default:
            return nullptr;
    }
}

// The button a group is (its index in kPillActions), or -1.
int PillActionOfGroup(PillGroup group) {
    for (size_t i = 0; i < ARRAYSIZE(kPillActions); i++) {
        if (kPillActions[i].group == group) {
            return (int)i;
        }
    }
    return -1;
}

int PillActionIndex(IslandPref pref) {
    for (size_t i = 0; i < ARRAYSIZE(kPillActions); i++) {
        if (kPillActions[i].pref == pref) {
            return (int)i;
        }
    }
    return -1;
}

// A pill action's option set in pillActions.
void SetPillActionBit(IslandPref pref, bool on) {
    const int index = PillActionIndex(pref);
    if (index >= 0) {
        g_settings.pillActions = on ? g_settings.pillActions | (1u << index)
                                    : g_settings.pillActions & ~(1u << index);
    }
}

// The groups that go online (weather, updates) show only with their own
// option on: an app's own icons can hide them, never turn them on.
bool OnlineGroupAllowed(PillGroup group) {
    switch (group) {
        case PillGroup::Weather:
            return g_settings.islandWeather;
        case PillGroup::Updates:
            return g_settings.islandUpdates;
        default:
            return true;
    }
}

