// The order chosen (the island's thread, or while it's stopped), kept as
// text (see EncodePillOrder).
std::vector<PillGroup> g_pillOrder;

// An order of the pill's groups as text: a character each, from '0' (kept
// for all apps in "islandOrder", and for an app in its place), and a '-' for
// each separator (older versions leave those out).
std::wstring EncodePillOrder(const std::vector<PillGroup>& order) {
    std::wstring text;
    for (PillGroup group : order) {
        text += IsPillSeparator(group) ? L'-' : (WCHAR)(L'0' + (int)group);
    }
    return text;
}

// The group a missing one goes after (see DecodePillOrder): the one before
// it in the enum, with the control center's buttons together, and the
// media's parts after the note (they were in it).
int GroupBefore(PillGroup group, int index) {
    if (group == PillGroup::MediaTitle) {
        return (int)PillGroup::Media;
    }
    if (group == PillGroup::MediaButtons) {
        return (int)PillGroup::MediaTitle;
    }
    if (group == PillGroup::Lyrics) {
        return (int)PillGroup::MediaButtons;
    }
    if (group == PillGroup::AiUsage) {
        return (int)PillGroup::Usage;
    }
    if (group == PillGroup::GlazeWorkspaces) {
        return (int)PillGroup::KomorebiLayout;
    }
    if (group == PillGroup::Pet) {
        return (int)PillGroup::Clock;
    }
    if (group == PillGroup::Shelf) {
        return (int)PillGroup::Folders;
    }
    const int action = PillActionOfGroup(group);
    return action > 0 ? (int)kPillActions[action - 1].group : index - 1;
}

// The groups read back (each once), and the ones missing (all of them the
// first time, or a new one) after the group that comes before them in the
// usual order (see GroupBefore).
std::vector<PillGroup> DecodePillOrder(std::wstring_view text) {
    std::vector<PillGroup> order;
    int separators = 0;
    for (WCHAR c : text) {
        // (A separator: the next number of them, up to the most.)
        if (c == L'-') {
            if (separators < kMaxPillSeparators) {
                order.push_back((PillGroup)(kPillGroups + separators++));
            }
            continue;
        }
        if (c < L'0' || c >= L'0' + kPillGroups) {
            continue;
        }
        const auto group = (PillGroup)(c - L'0');
        if (std::find(order.begin(), order.end(), group) == order.end()) {
            order.push_back(group);
        }
    }
    for (int i = 0; i < kPillGroups; i++) {
        const auto group = (PillGroup)i;
        if (std::find(order.begin(), order.end(), group) != order.end()) {
            continue;
        }
        auto at = order.begin();
        const int before = GroupBefore(group, i);
        if (auto it = std::find(order.begin(), order.end(), (PillGroup)before);
            it != order.end() && before != i - 1) {
            at = it + 1;
        } else {
            for (int j = before; j >= 0; j--) {
                it = std::find(order.begin(), order.end(), (PillGroup)j);
                if (it != order.end()) {
                    at = it + 1;
                    break;
                }
            }
        }
        order.insert(at, group);
    }
    return order;
}

void LoadPillOrder() {
    g_pillOrder =
        DecodePillOrder(GetWholeStringValue(
            L"islandOrder", kPillGroups + kMaxPillSeparators + 1));
}

void SavePillOrder() {
    StoreProfileString(L"islandOrder", EncodePillOrder(g_pillOrder).c_str());
}

// The other apps' tray icons as arranged on the island, each look its own
// like the pill's order (the main settings and the islands following them,
// a profile, another monitor's profile): the ones pinned on the pill, the
// order they were put in (the others after them, in Windows' order) and,
// for pinned ones put elsewhere on the pill than with the tray, the item
// they're beside (see TrayAnchor).
std::vector<std::wstring> g_trayPinned;
std::vector<std::wstring> g_trayOrder;
std::vector<std::pair<std::wstring, int>> g_trayAnchors;
// (Remembered for icons not there now too, up to this many.)
constexpr size_t kTrayOrderMax = 64;

// A pinned icon's place: -1 with the tray, a group's number after that
// group, or TrayAnchorBefore(group) before it.
int TrayAnchorBefore(PillGroup group) {
    return -(int)group - 2;
}

int TrayAnchor(const std::wstring& key) {
    for (const auto& [anchored, anchor] : g_trayAnchors) {
        if (anchored == key) {
            return anchor;
        }
    }
    return -1;
}

std::vector<std::wstring> DecodeTrayKeys(std::wstring_view text) {
    std::vector<std::wstring> keys;
    while (!text.empty()) {
        const size_t end = text.find(L'\n');
        if (const std::wstring_view key = text.substr(0, end); !key.empty()) {
            keys.emplace_back(key);
        }
        if (end == std::wstring_view::npos) {
            break;
        }
        text.remove_prefix(end + 1);
    }
    return keys;
}

std::wstring EncodeTrayKeys(const std::vector<std::wstring>& keys) {
    std::wstring text;
    for (const auto& key : keys) {
        text += (text.empty() ? L"" : L"\n") + key;
    }
    return text;
}

// "anchor<TAB>key" lines.
std::vector<std::pair<std::wstring, int>> DecodeTrayAnchors(
    std::wstring_view text) {
    std::vector<std::pair<std::wstring, int>> anchors;
    for (const auto& line : DecodeTrayKeys(text)) {
        const size_t tab = line.find(L'\t');
        const int anchor = _wtoi(line.c_str());
        // (Beside the tray's own items: with the tray.)
        if (tab != std::wstring::npos && anchor != -1 &&
            anchor != (int)PillGroup::Tray &&
            anchor != TrayAnchorBefore(PillGroup::Tray) &&
            anchor >= TrayAnchorBefore((PillGroup)(kPillGroups - 1)) &&
            anchor < kPillGroups) {
            anchors.push_back({line.substr(tab + 1), anchor});
        }
    }
    return anchors;
}

std::wstring EncodeTrayAnchors(
    const std::vector<std::pair<std::wstring, int>>& anchors) {
    std::wstring text;
    for (const auto& [key, anchor] : anchors) {
        text += (text.empty() ? L"" : L"\n") + std::to_wstring(anchor) + L"\t" +
                key;
    }
    return text;
}

void LoadTrayArrangement() {
    g_trayPinned = DecodeTrayKeys(GetWholeStringValue(L"trayPinned", 8192));
    g_trayOrder = DecodeTrayKeys(GetWholeStringValue(L"trayOrder", 8192));
    g_trayAnchors =
        DecodeTrayAnchors(GetWholeStringValue(L"trayAnchors", 8192));
}

void SaveTrayArrangement() {
    StoreProfileString(L"trayPinned", EncodeTrayKeys(g_trayPinned).c_str());
    StoreProfileString(L"trayOrder", EncodeTrayKeys(g_trayOrder).c_str());
    StoreProfileString(L"trayAnchors",
                       EncodeTrayAnchors(g_trayAnchors).c_str());
}

// Another app's tray icon dragged to another place (on the pill, or in the
// list of the ones not pinned): where it would go.
struct TrayDrop {
    // The island it goes on (none: back where it was).
    Island* island = nullptr;
    bool pinned = false;
    int anchor = -1;
    // Put before this icon, or after `after`, or after the ones there.
    std::wstring before;
    std::wstring after;
    // The line showing where, in that island's window.
    D2D1_RECT_F mark{};
};

// The icon held (see Island::DragTrayIcon and TrayListPanel::DragIcon): its
// key, the island whose icons they are, from its panel's list or not, where
// it was pressed, and whether it moved far enough to be dragged.
struct TrayDrag {
    std::wstring key;
    Island* owner = nullptr;
    bool fromList = false;
    POINT from{};
    bool moved = false;
    TrayDrop drop;
};
TrayDrag g_trayDrag;

// An item of the pill held with Ctrl and dragged to another place (see
// Island::DragGroup, islandOrderDrag): its group, the island it's from,
// where it was pressed, whether it moved far enough, and where it would go:
// the island under the mouse (another notch's too), the group it goes after
// or before there (none: alone there), and the line showing where, in that
// island's window.
struct GroupDrag {
    int group = -1;
    Island* owner = nullptr;
    POINT from{};
    bool moved = false;
    Island* island = nullptr;
    int after = -1;
    int before = -1;
    D2D1_RECT_F mark{};
};
GroupDrag g_groupDrag;

// The battery's charge now, or -1 on a computer without one.
int BatteryPercentNow() {
    SYSTEM_POWER_STATUS power;
    return GetSystemPowerStatus(&power) && !(power.BatteryFlag & 128) &&
                   power.BatteryFlag != 255 &&
                   power.BatteryLifePercent <= 100
               ? power.BatteryLifePercent
               : -1;
}

// The notches (the Fixed style's, see islandNotches): one in the middle,
// two at the screen's corners, or three. Each group goes in the left (0),
// middle (1) or right (2) one, kept as a figure per group in
// "islandNotchSides"; with two, the middle's go in the left one; with one,
// all of them in it. In each notch, the groups keep the pill's order.
constexpr int kMaxNotches = 3;
uint8_t g_notchSides[kPillGroups];

// The media's parts (new groups, see PillGroup::MediaTitle) in the note's
// notch, for sides kept before them (`length`: how many were kept).
void FollowMediaNotch(size_t length) {
    for (PillGroup part : {PillGroup::MediaTitle, PillGroup::MediaButtons}) {
        if ((size_t)part >= length) {
            g_notchSides[(int)part] = g_notchSides[(int)PillGroup::Media];
        }
    }
}

uint8_t DefaultNotchSide(PillGroup group) {
    switch (group) {
        case PillGroup::Clock:
        case PillGroup::Bell:
        case PillGroup::Media:
        case PillGroup::Pet:
            return 1;
        case PillGroup::Apps:
        case PillGroup::Usage:
        case PillGroup::Notes:
        case PillGroup::Tasks:
        case PillGroup::Shortcuts:
        case PillGroup::Weather:
        case PillGroup::Updates:
        case PillGroup::Profiles:
        case PillGroup::Desktops:
        case PillGroup::Folders:
        case PillGroup::Wallpaper:
        case PillGroup::KomorebiLayout:
        case PillGroup::GlazeWorkspaces:
        case PillGroup::FocusedApp:
        case PillGroup::WorldClocks:
        case PillGroup::Countdown:
            return 0;
        default:
            return 2;
    }
}

void LoadNotchSides() {
    const std::wstring value =
        GetWholeStringValue(L"islandNotchSides", kPillGroups + 1);
    const size_t length = value.size();
    for (int i = 0; i < kPillGroups; i++) {
        const WCHAR c = (size_t)i < length ? value[i] : 0;
        g_notchSides[i] = c >= L'0' && c <= L'2'
                              ? (uint8_t)(c - L'0')
                              : DefaultNotchSide((PillGroup)i);
    }
    FollowMediaNotch(length);
}

void SaveNotchSides() {
    std::wstring text;
    for (int i = 0; i < kPillGroups; i++) {
        text += (WCHAR)(L'0' + g_notchSides[i]);
    }
    StoreProfileString(L"islandNotchSides", text.c_str());
}

// How many notches the island has (none: not the Fixed style, or its pill).
int NotchCountWanted() {
    return g_settings.islandBar       ? 0
           : g_settings.islandReserve ? g_settings.islandNotches
                                      : g_settings.islandPillNotches;
}

// The per-app lists (see IslandPlace): one for each style, each keeping what
// that style can change for the app in front (see AppPlaceKeepsSpot).
constexpr int kAppPlacesIsland = 0;
constexpr int kAppPlacesFixed = 1;
constexpr int kAppPlacesBar = 2;

// The list a style uses; none for the Island style with notches (each notch
// keeps its place and items for every app).
int AppPlacesStyleOf(bool bar, bool fixed, int notches) {
    return bar            ? kAppPlacesBar
           : fixed        ? kAppPlacesFixed
           : notches == 0 ? kAppPlacesIsland
                          : -1;
}

int AppPlacesStyle() {
    return AppPlacesStyleOf(g_settings.islandBar, g_settings.islandReserve,
                            NotchCountWanted());
}

// The places, icons and order per app: in every style but the Island one
// with notches.
bool PerAppPlacesOn() {
    return AppPlacesStyle() >= 0;
}

// Where the notches are (0 left, 1 middle, 2 right), left to right.
std::vector<int> NotchPlaces(int count) {
    return count >= 3   ? std::vector<int>{0, 1, 2}
           : count == 2 ? std::vector<int>{0, 2}
           : count == 1 ? std::vector<int>{1}
                        : std::vector<int>{};
}

// The notch a group is in, with that many.
int NotchOfGroup(PillGroup group, int count) {
    // (Not a separator: see PillEntryNotch.)
    if ((int)group >= kPillGroups) {
        return count <= 1 ? 1 : 0;
    }
    const int side = g_notchSides[(int)group];
    return count <= 1 ? 1 : count == 2 ? (side == 2 ? 2 : 0) : side;
}

// The notch of an item of an order: a group's own, a separator's the one of
// the group before it (the one after it, at the start), so it stays with
// that group's items.
int PillEntryNotch(const std::vector<PillGroup>& order,
                   size_t index,
                   int count) {
    if (!IsPillSeparator(order[index])) {
        return NotchOfGroup(order[index], count);
    }
    for (size_t i = index; i-- > 0;) {
        if (!IsPillSeparator(order[i])) {
            return NotchOfGroup(order[i], count);
        }
    }
    for (size_t i = index + 1; i < order.size(); i++) {
        if (!IsPillSeparator(order[i])) {
            return NotchOfGroup(order[i], count);
        }
    }
    return count <= 1 ? 1 : 0;
}

// How much each separator of an order shows (0: not at all): one between two
// groups that show, as much as the one before it does (it grows in and out
// with them); not one at an end, with nothing shown between it and the
// next, or after another one. `shown`: how much each group shows (0 for
// none), and for a separator whether it's this island's (above 0) or
// another notch's.
std::vector<float> PillSeparatorAmounts(const std::vector<PillGroup>& order,
                                        const std::vector<float>& shown) {
    std::vector<float> amounts(order.size(), 0.0f);
    float shownBefore = 0;
    size_t waiting = order.size();
    for (size_t i = 0; i < order.size(); i++) {
        if (IsPillSeparator(order[i])) {
            if (shown[i] > 0 && shownBefore > 0 && waiting == order.size()) {
                waiting = i;
            }
        } else if (shown[i] > 0.001f) {
            if (waiting < order.size()) {
                amounts[waiting] = std::min(shownBefore, 1.0f);
                waiting = order.size();
            }
            shownBefore = shown[i];
        }
    }
    return amounts;
}

void SetPillOrder(const std::vector<PillGroup>& order);

// How big the notches' curves are, in percent: the round corners under them
// (a quarter of their height times the strength, at 100%), and the curves
// beside them, growing faster (wide and sweeping at 200%). The strength
// makes 100% half again as big as a quarter of their height (the default,
// 75%, a little more than that quarter).
constexpr int kNotchCurveMin = 0;
constexpr int kNotchCurveMax = 200;
constexpr int kNotchCurveDefault = 75;
constexpr int kNotchCurveStep = 5;
constexpr float kNotchCurveStrength = 1.5f;

float NotchCurveAmount() {
    return g_settings.islandNotchCurve / 100.0f * kNotchCurveStrength;
}

float NotchRadius(float height) {
    return std::round(height / 4 * NotchCurveAmount());
}

float NotchShoulder(float height) {
    const float amount = NotchCurveAmount();
    return std::round(height / 4 * amount * amount);
}

