// A fill color's row's kind (kFillDownloads...), -1 for the other rows.
int FillChoiceKind(int id) {
    return id == kChoiceFillColor         ? kFillDownloads
           : id == kChoiceFillCopyColor   ? kFillCopies
           : id == kChoiceFillChargeColor ? kFillCharge
                                          : -1;
}

// The choices whose buttons show a dot of their color: the fill's, the
// visualizer's, the charging battery's, Faísca's and the Vice theme's.
bool ChoiceHasDots(int id) {
    return FillChoiceKind(id) >= 0 || id == kChoiceVisualizerColor ||
           id == kChoiceBatteryChargeColor || id == kChoicePetColor ||
           id == kChoiceViceColors;
}

