    // What only the main island does (it shows the alerts and takes the
    // shortcuts): dimmed in another monitor's island's settings.
    static bool MainIslandOnly(IslandPref pref) {
        switch (pref) {
            case IslandPref::OwnNotifications:
            case IslandPref::ShortcutNotifications:
            case IslandPref::ShortcutControl:
            case IslandPref::MinimizeKey:
            case IslandPref::ClickThroughKey:
            case IslandPref::CapsLock:
            case IslandPref::LauncherKey:
            case IslandPref::NumLock:
            case IslandPref::StatusNotices:
            case IslandPref::NoticeCharger:
            case IslandPref::NoticeLowBattery:
            case IslandPref::NoticeBluetooth:
            case IslandPref::NoticeDnd:
            case IslandPref::NoticeBluetoothLow:
            case IslandPref::NoticeDesktop:
            case IslandPref::SongNotice:
            case IslandPref::Banner:
            case IslandPref::BannerMinimized:
            case IslandPref::HideWindowsBanners:
            case IslandPref::WebPictures:
            case IslandPref::WhatsNewNotice:
                return true;
            default:
                return false;
        }
    }
    // A slider dimmed (it still moves, for later): the distance from the
    // edge with the bar or the notches, the speed without animations, the
    // delay without auto-hide, the notches' curves without them, the line's
    // with the bar, the title's width without it, the pill's height with the
    // bar, its corners with the bar or the notches, the glass's blur without
    // the glass, the grid's columns without the grid, and the visualizer's
    // sensitivity and bars without it.
    static bool SliderDisabled(int slider) {
        // (The media sliders come before the visualizer's below.)
        if (slider == kSliderPetBusy) {
            return !g_settings.islandPet || !g_settings.islandPetReacts;
        }
        if (slider == kSliderPetSize) {
            return !g_settings.islandPet;
        }
        if (slider == kSliderPetRoom) {
            return !PetOnLine();
        }
        // (The speed with the animated neon only.)
        if (slider == kSliderViceSpeed) {
            return !ViceThemeOn() || !g_settings.islandViceFlow;
        }
        if (slider == kSliderViceStrength) {
            return !ViceThemeOn();
        }
        if (slider == kSliderPetSoundVolume) {
            return !g_settings.islandPet ||
                   !g_settings.islandPetSounds;
        }
        if (slider == kSliderMediaButtons) {
            return !g_mediaButtonsInPill;
        }
        if (slider == kSliderMediaPanel) {
            return !MediaPanelCanOpen();
        }
        const bool bar = g_settings.islandBar;
        const bool notches = NotchCountWanted() > 0;
        return ((slider == 1 || slider == 13) && (bar || notches)) ||
               (slider == 2 && AnimationLevel() >= 2) ||
               (slider == 5 && !g_settings.islandAutoHide) ||
               (slider == 6 && !notches) ||
               (slider == 12 && bar) ||
               ((slider == 8 || slider == 9) && bar &&
                !(g_settings.islandAutoHide && g_settings.islandBarAutoHide)) ||
               (slider == 11 && (!g_mediaTitleInPill ||
                                 g_settings.islandMediaCoverOnly)) ||
               (slider == 16 && !g_settings.islandLiquidGlass) ||
               (slider == 17 && g_settings.islandTrayStyle != 1) ||
               // (The icons before scrolling: only opening in the pill,
               // the grid has its columns.)
               (slider == 3 && g_settings.islandTrayStyle != 0) ||
               (slider >= 18 && slider != 19 &&
                !g_settings.islandVisualizer);
    }
    // An option that depends on another one being on (or the main island's
    // only, on another one).
    static bool PrefDisabled(IslandPref pref) {
        const bool notches = NotchCountWanted() > 0;
        return (OtherIslandShown() && MainIslandOnly(pref)) ||
               (pref == IslandPref::FollowMouse &&
                (GetIslandPref(IslandPref::AllMonitors) || notches)) ||
               ((pref == IslandPref::FreeDrag ||
                 pref == IslandPref::VerticalSides ||
                 pref == IslandPref::Frosted) &&
                notches) ||
               (pref == IslandPref::Frosted &&
                (!g_transparencyEffects || g_settings.islandLiquidGlass)) ||
               ((pref == IslandPref::NotchEach ||
                 pref == IslandPref::NotchHideEmpty) &&
                !notches) ||
               ((pref == IslandPref::MinimizeButton ||
                 pref == IslandPref::ArrowPins) &&
                g_settings.islandBar) ||
               // (The Bar's line brings the edge zone back too.)
               (pref == IslandPref::ZoneAsPill && g_settings.islandBar &&
                !(g_settings.islandAutoHide && g_settings.islandBarAutoHide)) ||
               (pref == IslandPref::BarCorners &&
                GetIslandPref(IslandPref::Bar) != 1) ||
               (pref == IslandPref::BarFixedSides &&
                (GetIslandPref(IslandPref::Bar) != 1 ||
                 !GetIslandPref(IslandPref::ClockCenter))) ||
               (pref == IslandPref::BarAutoHide &&
                (GetIslandPref(IslandPref::Bar) != 1 ||
                 !GetIslandPref(IslandPref::AutoHide))) ||
               (pref == IslandPref::GlassTranslucent &&
                !GetIslandPref(IslandPref::LiquidGlass)) ||
               (pref == IslandPref::ClockSeconds &&
                !GetIslandPref(IslandPref::Clock)) ||
               ((pref == IslandPref::CountdownEvents ||
                 pref == IslandPref::CountdownAlarms ||
                 pref == IslandPref::CountdownTimer ||
                 pref == IslandPref::CountdownPomodoro) &&
                !GetIslandPref(IslandPref::Countdown)) ||
               ((pref == IslandPref::AiClaude || pref == IslandPref::AiCodex ||
                 pref == IslandPref::AiCustom) &&
                !GetIslandPref(IslandPref::AiUsage)) ||
               (pref == IslandPref::FocusedTitle &&
                !GetIslandPref(IslandPref::FocusedApp)) ||
               (pref == IslandPref::WeatherCards &&
                !GetIslandPref(IslandPref::Weather)) ||
               (pref == IslandPref::DndSilent &&
                !GetIslandPref(IslandPref::OwnNotifications)) ||
               (pref == IslandPref::DownloadStalled &&
                !GetIslandPref(IslandPref::DownloadFill)) ||
               (pref == IslandPref::FolderThumbnails &&
                !GetIslandPref(IslandPref::Folders)) ||
               (pref == IslandPref::TimerLine &&
                !GetIslandPref(IslandPref::Timer)) ||
               (pref == IslandPref::GlassLight &&
                !GetIslandPref(IslandPref::LiquidGlass)) ||
               (pref == IslandPref::LyricsIcon &&
                !GetIslandPref(IslandPref::Lyrics)) ||
               (pref == IslandPref::ArrowPins &&
                (!GetIslandPref(IslandPref::AutoHide) ||
                 !GetIslandPref(IslandPref::MinimizeButton))) ||
               (pref == IslandPref::MediaAlways &&
                !GetIslandPref(IslandPref::Media)) ||
               (pref == IslandPref::MediaPlayOnly &&
                !GetIslandPref(IslandPref::MediaButtons)) ||
               // (The power button's actions and its question, in a row.)
               (pref >= IslandPref::PowerSleep &&
                pref <= IslandPref::PowerConfirm &&
                !GetIslandPref(IslandPref::Power)) ||
               (pref == IslandPref::BannerMarquee &&
                !GetIslandPref(IslandPref::Banner)) ||
               (pref == IslandPref::BannerApart &&
                !GetIslandPref(IslandPref::Banner)) ||
               (pref == IslandPref::BarClearDesktop &&
                !GetIslandPref(IslandPref::BarClear)) ||
               (pref == IslandPref::HideClockEdge &&
                !GetIslandPref(IslandPref::HideClock)) ||
               (pref == IslandPref::MediaCoverOnly &&
                !GetIslandPref(IslandPref::MediaTitle)) ||
               (pref == IslandPref::MediaTimesAlways &&
                (!MediaPanelCanOpen() ||
                 g_settings.islandMediaStyle != kMediaStylePixel)) ||
               (pref == IslandPref::MediaTotalTime && !MediaPanelCanOpen()) ||
               (pref == IslandPref::NoticeCharger &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::NoticeLowBattery &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::NoticeBluetooth &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::NoticeBluetoothLow &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::NoticeDnd &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::NoticeDesktop &&
                !GetIslandPref(IslandPref::StatusNotices)) ||
               (pref == IslandPref::BellWindows &&
                !GetIslandPref(IslandPref::Bell)) ||
               (pref == IslandPref::WorldClocksInClock &&
                !GetIslandPref(IslandPref::WorldClocks)) ||
               (pref == IslandPref::VlcTitle &&
                !GetIslandPref(IslandPref::Media)) ||
               (pref == IslandPref::MusicLine &&
                !GetIslandPref(IslandPref::Media)) ||
               (pref == IslandPref::SongNotice &&
                !GetIslandPref(IslandPref::Media)) ||
               (pref == IslandPref::MediaWheelReverse &&
                !GetIslandPref(IslandPref::MediaWheel)) ||
               (pref == IslandPref::BannerClickOutside &&
                !GetIslandPref(IslandPref::Banner)) ||
               (pref == IslandPref::GlazeHideEmpty &&
                !GetIslandPref(IslandPref::GlazeWorkspaces)) ||
               (pref == IslandPref::PetLine &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::ActivityNotices &&
                !GetIslandPref(IslandPref::LiveActivities)) ||
               (pref == IslandPref::ActivityCards &&
                !GetIslandPref(IslandPref::LiveActivities)) ||
               (pref == IslandPref::PetMoodColor &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetFollow &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetDance &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetReacts &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetLeak &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetCare &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetGames &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetSounds &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetGlow &&
                !GetIslandPref(IslandPref::Pet)) ||
               (pref == IslandPref::PetReactAll &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactNotify &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactFiles &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactDownload &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactScreenshot &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactVolume &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactUsb &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactCharger &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactWifiDown &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactWifiUp &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactSong &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactPomodoro &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::PetReactReminder &&
                !GetIslandPref(IslandPref::PetReacts)) ||
               (pref == IslandPref::TimerFill &&
                !GetIslandPref(IslandPref::Timer)) ||
               (pref == IslandPref::TimerFillOnly &&
                !GetIslandPref(IslandPref::TimerFill)) ||
               (pref == IslandPref::CalendarTasks &&
                !GetIslandPref(IslandPref::TaskDates)) ||
               (pref == IslandPref::PetAskPlay &&
                !GetIslandPref(IslandPref::PetCare)) ||
               ((pref == IslandPref::ViceFlow ||
                 pref == IslandPref::ViceBlack ||
                 pref == IslandPref::ViceOwnBack ||
                 pref == IslandPref::VicePause) &&
                !ViceThemeOn()) ||
               (pref == IslandPref::ViceBlack &&
                g_settings.islandViceOwnBack) ||
               // (The timer's own item shows them, see
               // Island::UpdateExtraItems.)
               ((pref == IslandPref::CountdownTimer ||
                 pref == IslandPref::CountdownPomodoro) &&
                GetIslandPref(IslandPref::Timer)) ||
               (pref == IslandPref::VolumePercent &&
                !GetIslandPref(IslandPref::Volume)) ||
               (pref == IslandPref::BatteryPercent &&
                !GetIslandPref(IslandPref::Battery)) ||
               (pref == IslandPref::TrayOpen &&
                (!GetIslandPref(IslandPref::Tray) ||
                 GetIslandPref(IslandPref::TrayStyle) != 0)) ||
               // (The Fixed style hiding as its line keeps no strip.)
               (pref == IslandPref::Frosted &&
                (!GetIslandPref(IslandPref::Bar) ||
                 (GetIslandPref(IslandPref::Bar) == 2 &&
                  GetIslandPref(IslandPref::AutoHide)))) ||
               (pref == IslandPref::MonthNumber &&
                !GetIslandPref(IslandPref::ClockDate)) ||
               (pref == IslandPref::WeekdayFull &&
                !GetIslandPref(IslandPref::ClockWeekday)) ||
               (pref == IslandPref::MediaMarquee &&
                !GetIslandPref(IslandPref::MediaTitle)) ||
               (pref == IslandPref::LyricsInTitle &&
                (!GetIslandPref(IslandPref::Lyrics) ||
                 !GetIslandPref(IslandPref::MediaTitle))) ||
               (pref == IslandPref::VisualizerSmooth &&
                !GetIslandPref(IslandPref::Visualizer)) ||
               ((pref == IslandPref::BannerMinimized ||
                 pref == IslandPref::HideWindowsBanners ||
                 pref == IslandPref::WebPictures) &&
                !GetIslandPref(IslandPref::Banner)) ||
               (pref == IslandPref::KomorebiLayout && g_komorebiFound == 0) ||
               // (Windows reports no temperature: one already on stays free
               // to turn off.)
               (pref == IslandPref::UsageCpuTemp && g_cpuTempFound == 0 &&
                !GetIslandPref(IslandPref::UsageCpuTemp)) ||
               (pref == IslandPref::KomorebiHideEmpty &&
                !GetIslandPref(IslandPref::KomorebiLayout)) ||
               // (The Bar hides by the minimize shortcut, no auto-hide.)
               (pref == IslandPref::HideClock && !g_settings.islandBar &&
                (!g_settings.islandAutoHide || notches)) ||
               (pref == IslandPref::HideClockEdge && !g_settings.islandBar &&
                (!g_settings.islandAutoHide || notches)) ||
               ((pref == IslandPref::BarClear ||
                 pref == IslandPref::BarClearDesktop) &&
                (GetIslandPref(IslandPref::Bar) != 1 ||
                 GetIslandPref(IslandPref::LiquidGlass)));
    }
