// Records as one compact text for Wh_SetStringValue:
// "PG1|<game 0>|...|<game 4>", a game being its results "value,date,extra"
// joined by ";" (the value in tenths). "\" escapes "\", ",", ";" and "|".
std::wstring PetGameEscape(const std::wstring& text) {
    std::wstring out;
    for (WCHAR c : text) {
        if (c < 32) {
            c = L' ';
        }
        if (c == L'\\' || c == L',' || c == L';' || c == L'|') {
            out += L'\\';
        }
        out += c;
    }
    return out;
}

// `text` cut at the separators that aren't escaped (the pieces keep their
// escapes).
std::vector<std::wstring> PetGameSplit(const std::wstring& text,
                                       WCHAR separator) {
    std::vector<std::wstring> parts(1);
    for (size_t i = 0; i < text.size(); i++) {
        if (text[i] == L'\\' && i + 1 < text.size()) {
            parts.back() += text[i];
            parts.back() += text[++i];
        } else if (text[i] == separator) {
            parts.emplace_back();
        } else {
            parts.back() += text[i];
        }
    }
    return parts;
}

std::wstring PetGameUnescape(const std::wstring& text) {
    std::wstring out;
    for (size_t i = 0; i < text.size(); i++) {
        if (text[i] == L'\\' && ++i >= text.size()) {
            break;
        }
        out += text[i];
    }
    return out;
}

// A record's value as digits only (no sign), at most 12 of them.
bool PetGameParseTenths(const std::wstring& text, long long* tenths) {
    if (text.empty() || text.size() > 12) {
        return false;
    }
    long long value = 0;
    for (WCHAR c : text) {
        if (c < L'0' || c > L'9') {
            return false;
        }
        value = value * 10 + (c - L'0');
    }
    *tenths = value;
    return true;
}

// How far a click may be from a beat to count: 0 missed, 1 good, 2 perfect.
int PetRhythmJudge(double distance) {
    const double d = std::fabs(distance);
    return d < kPetRhythmPerfect ? 2 : d <= kPetRhythmGood ? 1 : 0;
}

// When the first of the 32 beats comes: 2.4 s from now on the music's beat
// (`phase`: when one fell, `period`: the gap, both seconds; a period outside
// 0.3 to 1.2 s means no beat known and the steady one is used).
double PetRhythmStart(double now, double phase, double period) {
    const double first = now + 2.4;
    if (period < 0.3 || period > 1.2) {
        return first;
    }
    return phase + std::ceil((first - phase) / period - 1e-9) * period;
}

// The reflex's result: the rounds' times averaged, plus the mistakes'
// penalties spread over the rounds (a mistake costs 300 ms of the total).
double PetReflexScore(const std::vector<int>& times, int penaltyMs) {
    if (times.empty()) {
        return 0;
    }
    double sum = 0;
    for (int ms : times) {
        sum += ms;
    }
    return (sum + penaltyMs) / times.size();
}

// The pet, falling from `prevY` to `y` (down is more), lands on a cloud at
// `cloudY` when it crosses just above its top and is over its width; a
// jump that tops out a little short of it (her body drawn over the cloud's
// puffs by then) still lands (#7559).
constexpr float kPetCloudLedge = 6;

bool PetCloudLands(float prevY,
                   float y,
                   float cloudY,
                   float petX,
                   float cloudX,
                   float cloudW) {
    return prevY <= cloudY - 10 + kPetCloudLedge && y >= cloudY - 10 &&
           std::fabs(petX - cloudX) < cloudW / 2 + 10;
}

// What falls in the fruit rain: fruit and drops to catch, rocks and bolts
// to dodge (catching one costs a life; letting it fall costs nothing).
enum class PetFruitItem { Fruit, Drop, Rock, Bolt };
constexpr bool PetFruitHazard(PetFruitItem item) {
    return item == PetFruitItem::Rock || item == PetFruitItem::Bolt;
}

// The next thing to fall, from two random numbers in [0, 1): once there
// are more than kPetFruitHazardFrom points, 24% of them are hazards (half
// rocks, half bolts); of the rest a quarter are drops.
constexpr int kPetFruitHazardFrom = 3;
constexpr float kPetFruitHazardShare = 0.24f;
PetFruitItem PetFruitKind(int score, float roll, float second) {
    if (score > kPetFruitHazardFrom && roll < kPetFruitHazardShare) {
        return second < 0.5f ? PetFruitItem::Rock : PetFruitItem::Bolt;
    }
    return second < 0.25f ? PetFruitItem::Drop : PetFruitItem::Fruit;
}

// Where the memory's cards go on a stage of w x h: 4 columns, 3 rows.
struct PetMemoryLayout {
    float cardW, cardH, gap, left, top;
};
PetMemoryLayout PetGameMemoryLayout(float w, float h) {
    const float gap = 10;
    const float cardW = std::max(
        std::min((w - 40 - gap * 3) / 4, (h - 56 - gap * 2) / 3 * 0.82f), 8.0f);
    const float cardH = cardW / 0.82f;
    return {cardW, cardH, gap, (w - (cardW * 4 + gap * 3)) / 2,
            40 + (h - 48 - (cardH * 3 + gap * 2)) / 2};
}

// A small xorshift, seeded for each round.
struct PetGameRng {
    uint32_t state = 2463534242u;
    void Seed(uint64_t seed) {
        state = (uint32_t)(seed ^ (seed >> 32)) * 2654435761u;
        if (!state) {
            state = 2463534242u;
        }
        for (int i = 0; i < 4; i++) {
            Next();
        }
    }
    uint32_t Next() {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        return state;
    }
    // 0 up to (not including) 1.
    float Float() { return (Next() >> 8) * (1.0f / 16777216.0f); }
};

D2D1_COLOR_F PetGameRgb(float r, float g, float b, float a = 1) {
    return {r / 255, g / 255, b / 255, a};
}

// A path built step by step (the games' shapes are made once, see
// PetGameShapes).
class PetGamePath {
   public:
    bool Open(ID2D1Factory* factory) {
        return SUCCEEDED(factory->CreatePathGeometry(m_path.put())) &&
               SUCCEEDED(m_path->Open(m_sink.put()));
    }
    void Begin(float x, float y, bool filled) {
        m_sink->BeginFigure({x, y}, filled ? D2D1_FIGURE_BEGIN_FILLED
                                           : D2D1_FIGURE_BEGIN_HOLLOW);
    }
    void Line(float x, float y) { m_sink->AddLine({x, y}); }
    void Quad(float cx, float cy, float x, float y) {
        const D2D1_QUADRATIC_BEZIER_SEGMENT curve{{cx, cy}, {x, y}};
        m_sink->AddQuadraticBezier(&curve);
    }
    void Cubic(float x1, float y1, float x2, float y2, float x, float y) {
        const D2D1_BEZIER_SEGMENT curve{{x1, y1}, {x2, y2}, {x, y}};
        m_sink->AddBezier(&curve);
    }
    // The circle's arc from angle a0 to a1 (radians; more is clockwise on
    // the screen), from the figure's current point.
    void ArcTo(float cx, float cy, float r, float a0, float a1) {
        m_sink->AddArc({{cx + r * std::cos(a1), cy + r * std::sin(a1)},
                        {r, r},
                        0,
                        a1 > a0 ? D2D1_SWEEP_DIRECTION_CLOCKWISE
                                : D2D1_SWEEP_DIRECTION_COUNTER_CLOCKWISE,
                        std::fabs(a1 - a0) > kPi
                            ? D2D1_ARC_SIZE_LARGE
                            : D2D1_ARC_SIZE_SMALL});
    }
    // A figure of only that arc.
    void Arc(float cx, float cy, float r, float a0, float a1) {
        Begin(cx + r * std::cos(a0), cy + r * std::sin(a0), false);
        ArcTo(cx, cy, r, a0, a1);
        End(false);
    }
    void End(bool closed) {
        m_sink->EndFigure(closed ? D2D1_FIGURE_END_CLOSED
                                 : D2D1_FIGURE_END_OPEN);
    }
    winrt::com_ptr<ID2D1PathGeometry> Finish() {
        if (!m_sink || FAILED(m_sink->Close())) {
            return nullptr;
        }
        return m_path;
    }

   private:
    winrt::com_ptr<ID2D1PathGeometry> m_path;
    winrt::com_ptr<ID2D1GeometrySink> m_sink;
};

// The shapes the games draw with, made once per Direct2D factory (they
// outlive the host's render targets). Memory icons are 1 wide: drawn scaled.
struct PetGameShapes {
    winrt::com_ptr<ID2D1Factory> factory;
    winrt::com_ptr<ID2D1StrokeStyle> roundCaps;
    winrt::com_ptr<ID2D1PathGeometry> drop, stem, wifi, speaker, waves, note,
        bell, rock, rockShine, bolt;

    void Make(ID2D1Factory* made) {
        if (factory.get() == made) {
            return;
        }
        *this = PetGameShapes();
        factory.copy_from(made);
        made->CreateStrokeStyle(
            D2D1::StrokeStyleProperties(D2D1_CAP_STYLE_ROUND,
                                        D2D1_CAP_STYLE_ROUND,
                                        D2D1_CAP_STYLE_ROUND,
                                        D2D1_LINE_JOIN_ROUND),
            nullptr, 0, roundCaps.put());
        PetGamePath path;
        // A drop of water, 18 wide.
        if (path.Open(made)) {
            path.Begin(0, -11, true);
            path.Cubic(9, -1, 7, 9, 0, 9);
            path.Cubic(-7, 9, -9, -1, 0, -11);
            path.End(true);
            drop = path.Finish();
        }
        // The fruit's stem.
        PetGamePath stemPath;
        if (stemPath.Open(made)) {
            stemPath.Begin(0, -6, false);
            stemPath.Quad(2, -12, 7, -13);
            stemPath.End(false);
            stem = stemPath.Finish();
        }
        PetGamePath wifiPath;
        if (wifiPath.Open(made)) {
            for (int i = 1; i <= 3; i++) {
                wifiPath.Arc(0, 0.32f, i * 0.2f, 1.22f * kPi, 1.78f * kPi);
            }
            wifi = wifiPath.Finish();
        }
        PetGamePath speakerPath;
        if (speakerPath.Open(made)) {
            speakerPath.Begin(-0.4f, -0.12f, true);
            speakerPath.Line(-0.22f, -0.12f);
            speakerPath.Line(0, -0.34f);
            speakerPath.Line(0, 0.34f);
            speakerPath.Line(-0.22f, 0.12f);
            speakerPath.Line(-0.4f, 0.12f);
            speakerPath.End(true);
            speaker = speakerPath.Finish();
        }
        PetGamePath wavesPath;
        if (wavesPath.Open(made)) {
            wavesPath.Arc(0.05f, 0, 0.2f, -0.9f, 0.9f);
            wavesPath.Arc(0.05f, 0, 0.36f, -0.9f, 0.9f);
            waves = wavesPath.Finish();
        }
        PetGamePath notePath;
        if (notePath.Open(made)) {
            notePath.Begin(-0.03f, 0.22f, false);
            notePath.Line(-0.03f, -0.3f);
            notePath.Line(0.35f, -0.4f);
            notePath.Line(0.35f, 0.12f);
            notePath.End(false);
            note = notePath.Finish();
        }
        PetGamePath bellPath;
        if (bellPath.Open(made)) {
            bellPath.Begin(-0.32f, 0.2f, true);
            bellPath.Quad(-0.26f, 0.08f, -0.26f, -0.06f);
            bellPath.ArcTo(0, -0.06f, 0.26f, kPi, 2 * kPi);
            bellPath.Quad(0.26f, 0.08f, 0.32f, 0.2f);
            bellPath.End(true);
            bell = bellPath.Finish();
        }
        // The rock and the bolt of the fruit rain.
        PetGamePath rockPath;
        if (rockPath.Open(made)) {
            rockPath.Begin(-10, -3, true);
            rockPath.Line(-5, -10);
            rockPath.Line(6, -9);
            rockPath.Line(11, -1);
            rockPath.Line(7, 9);
            rockPath.Line(-6, 9);
            rockPath.End(true);
            rock = rockPath.Finish();
        }
        PetGamePath shinePath;
        if (shinePath.Open(made)) {
            shinePath.Begin(-5, -8, true);
            shinePath.Line(4, -7);
            shinePath.Line(0, -2);
            shinePath.End(true);
            rockShine = shinePath.Finish();
        }
        PetGamePath boltPath;
        if (boltPath.Open(made)) {
            boltPath.Begin(2, -12, true);
            boltPath.Line(-7, 2);
            boltPath.Line(0, 2);
            boltPath.Line(-3, 12);
            boltPath.Line(8, -2);
            boltPath.Line(1, -2);
            boltPath.End(true);
            bolt = boltPath.Finish();
        }
    }
};

// What a game draws with while drawing.
struct PetGameInk {
    ID2D1RenderTarget* target;
    ID2D1SolidColorBrush* brush;
    // The stage's transform (DIPs to the target).
    D2D1_MATRIX_3X2_F base;
    // What is drawn fades in with this (the memory's cards dealt).
    mutable float fade = 1;

    void Color(D2D1_COLOR_F color, float alpha = 1) const {
        color.a *= alpha * fade;
        brush->SetColor(color);
    }
    void Dot(float x, float y, float r) const {
        target->FillEllipse(D2D1_ELLIPSE{{x, y}, r, r}, brush);
    }
    void Ring(float x, float y, float r, float width) const {
        target->DrawEllipse(D2D1_ELLIPSE{{x, y}, r, r}, brush, width);
    }
    void Card(const D2D1_RECT_F& rect, float r) const {
        target->FillRoundedRectangle(D2D1_ROUNDED_RECT{rect, r, r}, brush);
    }
    void CardLine(const D2D1_RECT_F& rect, float r, float width) const {
        target->DrawRoundedRectangle(D2D1_ROUNDED_RECT{rect, r, r}, brush,
                                     width);
    }
    // A place of its own: at (x, y), scaled and then turned (radians).
    D2D1::Matrix3x2F Matrix(float x,
                            float y,
                            float sx,
                            float sy,
                            float angle) const {
        return D2D1::Matrix3x2F::Scale(sx, sy) *
               D2D1::Matrix3x2F::Rotation(angle * 180 / kPi) *
               D2D1::Matrix3x2F::Translation(x, y) *
               *D2D1::Matrix3x2F::ReinterpretBaseType(&base);
    }
    void Place(float x, float y, float sx, float sy, float angle) const {
        target->SetTransform(Matrix(x, y, sx, sy, angle));
    }
    void Home() const { target->SetTransform(base); }
};

class PetGames {
   public:
    // ---- The host's side ----
    // Makes the texts' fonts (again when the island's font changed): call it
    // from the panel's Prepare.
    void Prepare(IDWriteFactory* dwrite) {
        const size_t fonts = FontsKey();
        if (!dwrite || (m_title && m_dwrite.get() == dwrite &&
                        m_fonts == fonts)) {
            return;
        }
        m_dwrite.copy_from(dwrite);
        m_fonts = fonts;
        constexpr auto kSemi = DWRITE_FONT_WEIGHT_SEMI_BOLD;
        constexpr auto kNormal = DWRITE_FONT_WEIGHT_NORMAL;
        m_hudLeft = Format(L"Segoe UI Variable Text", kSemi, 12.5f,
                           DWRITE_TEXT_ALIGNMENT_LEADING);
        m_hudRight = Format(L"Segoe UI Variable Text", kSemi, 12.5f,
                            DWRITE_TEXT_ALIGNMENT_TRAILING);
        m_title = Format(L"Segoe UI Variable Display", kSemi, 18,
                         DWRITE_TEXT_ALIGNMENT_CENTER);
        m_line = Format(L"Segoe UI Variable Text", kNormal, 12.5f,
                        DWRITE_TEXT_ALIGNMENT_CENTER);
        m_message = Format(L"Segoe UI Variable Text", kSemi, 14,
                           DWRITE_TEXT_ALIGNMENT_CENTER);
        m_count = Format(L"Segoe UI Variable Display", kSemi, 28,
                         DWRITE_TEXT_ALIGNMENT_CENTER);
    }
    // Puts a game on the stage, at its title screen. `area` is the stage's
    // size in pixels and `scale` the host's (DIP to pixel); `petColor` is
    // her color (the reflex game's target, an accent). `now`: when it is
    // put there (its title comes in from then; 0: no coming in).
    void Select(PetGameId id,
                D2D1_SIZE_F area,
                float scale,
                D2D1_COLOR_F petColor,
                double now = 0) {
        m_id = id;
        m_state = State::Title;
        m_screenWas = State::Playing;
        m_titleAt = now;
        m_ready = false;
        m_lit = false;
        m_petColor = petColor;
        Resize(area, scale);
    }
    // The stage changed size or scale (the panel was resized or rescaled).
    void Resize(D2D1_SIZE_F area, float scale) {
        m_scale = std::max(scale, 0.5f);
        m_w = std::max(area.width / m_scale, 120.0f);
        m_h = std::max(area.height / m_scale, 160.0f);
    }
    void SetPetColor(D2D1_COLOR_F color) { m_petColor = color; }
    // The music's beat for the rhythm game (call it before Start): when one
    // fell and the gap, in the seconds of `now`; (0, 0) when there is none.
    void SetBeat(double phase, double period) {
        m_beatPhase = phase;
        m_beatPeriod = period;
    }
    // Starts the selected game (a new round).
    void Start(double now) {
        m_rng.Seed((uint64_t)(now * 1000.0) + 7919ull * ++m_rounds);
        // (The screen it starts from goes away, see DrawScreens.)
        m_screenWas = m_state;
        m_startedAt = now;
        m_state = State::Playing;
        m_ready = true;
        switch (m_id) {
            case PetGameId::Fruit:
                InitFruit();
                break;
            case PetGameId::Rhythm:
                InitRhythm(now);
                break;
            case PetGameId::Clouds:
                InitClouds();
                break;
            case PetGameId::Memory:
                InitMemory(now);
                break;
            default:
                InitReflex(now);
                break;
        }
    }
    // Back to the title screen (the round is not kept).
    void Stop() {
        m_state = State::Title;
        m_ready = false;
        m_lit = false;
        m_events.clear();
    }
    bool Playing() const { return m_state == State::Playing; }
    bool Over() const { return m_state == State::Over; }
    PetGameId Game() const { return m_id; }
    // The rules and the animations of one frame; true while the host should
    // keep drawing frames. Call it after every input too, once, to find out
    // (a click can start a card flipping).
    bool Step(double now, double dt) {
        const float d = (float)std::clamp(dt, 0.0, 0.05);
        const State before = m_state;
        // The falling games follow the real time, in fixed steps: the
        // frame's `dt` is capped and follows the animations' speed, so a late
        // frame slowed them and how high a jump went changed with the frame
        // rate (a cloud skipped was missed by a hair, #7559).
        const bool falling =
            m_id == PetGameId::Fruit || m_id == PetGameId::Clouds;
        if (m_state == State::Playing && falling) {
            if (m_steppedAt > 0) {
                m_stepLeft += std::clamp(now - m_steppedAt, 0.0, 0.1);
            }
            m_steppedAt = now;
            while (m_stepLeft >= kPetGameStep && m_state == State::Playing) {
                m_stepLeft -= kPetGameStep;
                if (m_id == PetGameId::Fruit) {
                    StepFruit(now, (float)kPetGameStep);
                } else {
                    StepClouds(now, (float)kPetGameStep);
                }
            }
        } else {
            m_steppedAt = 0;
            m_stepLeft = 0;
        }
        if (m_state == State::Playing) {
            switch (m_id) {
                case PetGameId::Rhythm:
                    StepRhythm(now);
                    break;
                case PetGameId::Reflex:
                    StepReflex(now);
                    break;
                default:
                    break;
            }
        }
        bool moving = m_state == State::Playing && m_id != PetGameId::Memory;
        if (m_id == PetGameId::Memory && m_ready) {
            moving |= StepCards(now, d);
        }
        return moving || m_state != before;
    }
    // Idle but showing a clock (the memory game, waiting for a click): the
    // host may redraw about ten times a second.
    bool NeedsClock() const {
        return m_state == State::Playing && m_id == PetGameId::Memory;
    }
    // The looks that are not the rules still moving: a screen coming in or
    // going, the stage shaking, the memory's cards being dealt. The host
    // keeps frames while this is true (with Step); none with the
    // animations off.
    bool Animating(double now) const {
        const int level = AnimationLevel();
        if (level >= 2) {
            return false;
        }
        if (m_state == State::Title && m_titleAt > 0) {
            return now - m_titleAt < kPetGameScreenSeconds;
        }
        if (m_state == State::Over &&
            now - m_overAt < kPetGameScreenSeconds) {
            return true;
        }
        if (m_state == State::Playing && m_screenWas != State::Playing &&
            now - m_startedAt < kPetGameAwaySeconds) {
            return true;
        }
        if (level == 0 && now - m_shake < kPetGameShakeSeconds) {
            return true;
        }
        return m_id == PetGameId::Memory && m_ready &&
               now < m_startAt + kPetGameDealGap * kPetMemoryCards +
                         kPetGameDealSeconds;
    }
    // The mouse over the stage (pixels from its top left corner).
    void PointerMove(float x, float /*y*/) {
        m_ptrX = std::clamp(x / m_scale / m_w, 0.05f, 0.95f);
    }
    // A press on the stage: starts a round from a title or "game over"
    // screen, else it is the game's click.
    void PointerDown(float x, float y, double now) {
        if (m_state != State::Playing) {
            StartFromScreen(now);
        } else if (m_id == PetGameId::Memory) {
            ClickMemory(x / m_scale, y / m_scale, now);
        } else {
            Click(now);
        }
    }
    // A key: the arrows steer, Space and Enter act (they start a round on
    // the title). Escape is not taken. True when the key was used.
    bool Key(UINT vk, double now) {
        if (vk == VK_LEFT || vk == VK_RIGHT) {
            m_ptrX = std::clamp(m_ptrX + (vk == VK_LEFT ? -0.08f : 0.08f),
                                0.05f, 0.95f);
            return true;
        }
        if (vk != VK_SPACE && vk != VK_RETURN) {
            return false;
        }
        if (m_state != State::Playing) {
            StartFromScreen(now);
        } else if (m_id != PetGameId::Memory) {
            Click(now);
        }
        return true;
    }
    std::vector<PetGameEvent> TakeEvents() {
        std::vector<PetGameEvent> events;
        events.swap(m_events);
        return events;
    }
    // A round just ended and its result is already in the records: the host
    // saves EncodeRecords(Records()). True once per round.
    bool TakeFinished(PetGameId* id, PetGameRecord* record) {
        if (!m_finished) {
            return false;
        }
        m_finished = false;
        if (id) {
            *id = m_finishedId;
        }
        if (record) {
            *record = m_finalRecord;
        }
        return true;
    }
    // The kept results: set them after DecodeRecords, read them to save.
    void SetRecords(const PetGameRecords& records) { m_records = records; }
    const PetGameRecords& Records() const { return m_records; }
    // Draws the stage (its background, the game, the title / game over
    // texts) in `canvas.area`.
    void Draw(const PetGameCanvas& canvas, double now) {
        if (!canvas.target || !canvas.brush) {
            return;
        }
        ID2D1RenderTarget* target = canvas.target;
        D2D1_MATRIX_3X2_F was;
        target->GetTransform(&was);
        const D2D1_RECT_F& area = canvas.area;
        PetGameInk ink{target, canvas.brush, was};
        const float s = m_scale;
        ink.Color(PetGameRgb(7, 9, 11));
        target->FillRoundedRectangle(D2D1_ROUNDED_RECT{area, 10 * s, 10 * s},
                                     canvas.brush);
        target->PushAxisAlignedClip(area, D2D1_ANTIALIAS_MODE_ALIASED);
        ink.base = D2D1::Matrix3x2F::Scale(s, s) *
                   D2D1::Matrix3x2F::Translation(area.left, area.top) *
                   *D2D1::Matrix3x2F::ReinterpretBaseType(&was);
        // A hit shakes everything on the stage (not with the animations
        // off or partial).
        const double shaken = now - m_shake;
        if (AnimationLevel() == 0 && shaken >= 0 &&
            shaken < kPetGameShakeSeconds) {
            const float shake = (float)(std::sin(shaken * 60) * 7 *
                                        (1 - shaken / kPetGameShakeSeconds));
            ink.base = D2D1::Matrix3x2F::Translation(shake, 0) *
                       *D2D1::Matrix3x2F::ReinterpretBaseType(&ink.base);
        }
        ink.Home();
        winrt::com_ptr<ID2D1Factory> factory;
        target->GetFactory(factory.put());
        if (factory) {
            m_shapes.Make(factory.get());
        }
        switch (m_id) {
            case PetGameId::Fruit:
                DrawFruit(ink, canvas, now);
                break;
            case PetGameId::Rhythm:
                DrawRhythm(ink, canvas, now);
                break;
            case PetGameId::Clouds:
                DrawClouds(ink, canvas);
                break;
            case PetGameId::Memory:
                DrawMemory(ink, canvas, now);
                break;
            default:
                DrawReflex(ink, canvas, now);
                break;
        }
        DrawScreens(ink, now);
        target->PopAxisAlignedClip();
        target->SetTransform(was);
        ink.Color(PetGameRgb(255, 255, 255, 0.08f));
        target->DrawRoundedRectangle(
            D2D1_ROUNDED_RECT{{area.left + 0.5f, area.top + 0.5f,
                               area.right - 0.5f, area.bottom - 0.5f},
                              10 * s,
                              10 * s},
            canvas.brush, 1);
    }

    // ---- Records as text ----
    // (A text that isn't one gives false and no records.)
    static std::wstring EncodeRecords(const PetGameRecords& records) {
        std::wstring text = L"PG1";
        for (const auto& list : records) {
            text += L'|';
            for (size_t i = 0; i < list.size() && i < kPetGameTop; i++) {
                if (i) {
                    text += L';';
                }
                text += std::to_wstring(std::llround(list[i].value * 10)) +
                        L',' + PetGameEscape(list[i].date) + L',' +
                        PetGameEscape(list[i].extra);
            }
        }
        return text;
    }
    static bool DecodeRecords(const std::wstring& text, PetGameRecords* out) {
        PetGameRecords result;
        const std::vector<std::wstring> groups = PetGameSplit(text, L'|');
        const bool ok = groups.size() == (size_t)kPetGames + 1 &&
                        groups[0] == L"PG1";
        for (int game = 0; ok && game < kPetGames; game++) {
            if (groups[game + 1].empty()) {
                continue;
            }
            for (const std::wstring& entry :
                 PetGameSplit(groups[game + 1], L';')) {
                const std::vector<std::wstring> fields =
                    PetGameSplit(entry, L',');
                if (fields.size() != 3 || fields[0].empty()) {
                    continue;
                }
                long long tenths = 0;
                if (!PetGameParseTenths(fields[0], &tenths)) {
                    continue;
                }
                PetGameRecord record;
                record.value = tenths / 10.0;
                record.date = PetGameUnescape(fields[1]).substr(0, 40);
                record.extra = PetGameUnescape(fields[2]).substr(0, 64);
                PetGameAddRecord(result[game], record,
                                 PetGameLowerIsBetter((PetGameId)game));
            }
        }
        if (out) {
            *out = ok ? result : PetGameRecords();
        }
        return ok;
    }

    // ---- State (public: the unit tests look at it) ----
    enum class State { Title, Playing, Over };
    enum class CloudKind { Fixed, Move, Fade };
    enum class ReflexState { Wait, Lit };
    struct Item {
        float x, y, speed, spin;
        PetFruitItem kind;
    };
    // (`squish`: 1 as she lands on it, back to 0.)
    struct Cloud {
        float x, y, w, phase, gone;
        CloudKind kind;
        float squish = 0;
    };
    // (`dealAt`: when it is dealt.)
    struct Card {
        int icon;
        float up, target;
        bool done;
        double pop;
        double dealAt = 0;
    };
    struct Message {
        double at;
        std::wstring text;
        D2D1_COLOR_F color;
    };
    PetGameId m_id = PetGameId::Fruit;
    State m_state = State::Title;
    // The falling games' clock (see Step): the last step's time (0: none
    // yet), and the real time not stepped yet.
    double m_steppedAt = 0;
    double m_stepLeft = 0;
    // The round's data exists (a round started and not stopped).
    bool m_ready = false;
    float m_scale = 1, m_w = 360, m_h = 340;
    D2D1_COLOR_F m_petColor{0.247f, 0.816f, 0.788f, 1};
    PetGameRng m_rng;
    uint64_t m_rounds = 0;
    float m_ptrX = 0.5f;
    PetGameRecords m_records;
    std::vector<PetGameEvent> m_events;
    // The round just ended.
    bool m_finished = false;
    PetGameId m_finishedId = PetGameId::Fruit;
    PetGameRecord m_finalRecord;
    bool m_newRecord = false;
    double m_overAt = 0;
    // When the title came in, when the last round started and the screen
    // it started from (Playing: none).
    double m_titleAt = 0, m_startedAt = 0;
    State m_screenWas = State::Playing;
    // The music's beat.
    double m_beatPhase = 0, m_beatPeriod = 0;
    // Fruit and clouds: where she is across (0 to 1), her speed.
    float m_x = 0.5f, m_vx = 0;
    int m_score = 0;
    // Fruit.
    std::vector<Item> m_items;
    int m_lives = 3;
    float m_spawn = 0, m_speed = 1;
    // Rhythm (and memory's start time).
    double m_startAt = 0, m_period = 0.6;
    int m_next = 0, m_combo = 0, m_best = 0, m_hits = 0;
    std::vector<char> m_judged;  // 0 not yet, 1 missed, 2 good, 3 perfect
    std::vector<Message> m_messages;
    // Clouds.
    float m_py = 0, m_vy = 0, m_cam = 0, m_lastY = 0;
    std::vector<Cloud> m_clouds;
    // Memory.
    std::array<Card, kPetMemoryCards> m_cards{};
    int m_open[2]{-1, -1};
    int m_openCount = 0, m_moves = 0, m_pairs = 0;
    double m_closeAt = 0;
    // Reflex.
    int m_round = 0, m_penalty = 0, m_decoys = 0;
    std::vector<int> m_times;
    ReflexState m_reflex = ReflexState::Wait;
    double m_at = 0, m_shownAt = 0, m_until = 0, m_shake = -9, m_messageAt = -9;
    bool m_lit = false, m_onTarget = false;
    D2D1_COLOR_F m_color{};
    std::wstring m_reflexMessage;

   private:
    static void Spring(float& p, float& v, float target, float k, float d,
                       float dt) {
        v += (k * (target - p) - d * v) * dt;
        p += v * dt;
    }
    void Event(PetGameEvent event) { m_events.push_back(event); }

    // A round ends: its result goes into the records.
    void Finish(double now, double value, const std::wstring& extra) {
        m_state = State::Over;
        m_overAt = now;
        m_finishedId = m_id;
        m_finalRecord = {value, PetGameToday(), extra};
        m_newRecord = PetGameAddRecord(m_records[(int)m_id], m_finalRecord,
                                       PetGameLowerIsBetter(m_id));
        m_finished = true;
    }
    void StartFromScreen(double now) {
        if (m_state == State::Over && now - m_overAt < kPetGameOverGuard) {
            return;
        }
        Start(now);
    }
    // A click or Space in the games that use one.
    void Click(double now) {
        if (m_id == PetGameId::Rhythm) {
            ClickRhythm(now);
        } else if (m_id == PetGameId::Reflex) {
            ClickReflex(now);
        }
    }

    // ---- Fruit rain ----
    void InitFruit() {
        m_x = m_ptrX;
        m_vx = 0;
        m_items.clear();
        m_score = 0;
        m_lives = 3;
        m_spawn = 0.6f;
        m_speed = 1;
    }
    void StepFruit(double now, float dt) {
        Spring(m_x, m_vx, m_ptrX, 120, 16, dt);
        const float px = m_x * m_w, py = m_h - 34;
        m_spawn -= dt;
        m_speed += dt * 0.025f;
        if (m_spawn <= 0) {
            const float roll = m_rng.Float(), second = m_rng.Float();
            m_items.push_back({0.06f + m_rng.Float() * 0.88f, -12,
                               (75 + m_rng.Float() * 55) * m_speed,
                               m_rng.Float() * 6,
                               PetFruitKind(m_score, roll, second)});
            m_spawn = std::max(0.32f, 0.95f - m_score * 0.014f);
        }
        for (size_t i = 0; i < m_items.size();) {
            Item& item = m_items[i];
            const float before = item.y;
            item.y += item.speed * dt;
            item.spin += dt * 2;
            const bool hazard = PetFruitHazard(item.kind);
            if (item.y > py - 20 && before < py + 10 &&
                std::fabs(item.x * m_w - px) < 28) {
                if (hazard) {
                    // (A rock or a bolt caught: a life, not a point.)
                    m_lives--;
                    m_shake = now;
                    Event(PetGameEvent::Hurt);
                } else {
                    m_score++;
                    Event(item.kind == PetFruitItem::Drop
                              ? PetGameEvent::Drank
                              : PetGameEvent::Ate);
                }
            } else if (item.y > m_h + 12) {
                // (Letting a hazard fall is fine.)
                if (!hazard) {
                    m_lives--;
                    Event(PetGameEvent::Sad);
                }
            } else {
                i++;
                continue;
            }
            m_items.erase(m_items.begin() + i);
        }
        if (m_lives <= 0) {
            Finish(now, m_score, L"");
        }
    }
    void DrawFruit(const PetGameInk& ink,
                   const PetGameCanvas& canvas,
                   double now) {
        const float px = m_x * m_w, py = m_h - 34;
        const Item* lowest = nullptr;
        for (const Item& item : m_items) {
            switch (item.kind) {
                case PetFruitItem::Drop:
                    DrawDrop(ink, item.x * m_w, item.y);
                    break;
                case PetFruitItem::Rock:
                    DrawRock(ink, item.x * m_w, item.y, item.spin);
                    break;
                case PetFruitItem::Bolt:
                    DrawBolt(ink, item.x * m_w, item.y, now);
                    break;
                default:
                    DrawFruitPiece(ink, item.x * m_w, item.y, item.spin);
                    break;
            }
            // (She looks at the lowest thing she can eat.)
            if (!PetFruitHazard(item.kind) &&
                (!lowest || item.y > lowest->y)) {
                lowest = &item;
            }
        }
        DrawPet(canvas, px, py, 40,
                lowest ? std::clamp((lowest->x * m_w - px) / 120, -1.0f, 1.0f)
                       : 0,
                lowest ? -0.8f : 0, PetGamePose::Idle);
        if (m_state == State::Playing) {
            DrawHud(ink, std::to_wstring(m_score), false);
            for (int i = 0; i < 3; i++) {
                ink.Color(PetGameRgb(255, 138, 92));
                const float x = m_w - 17 - i * 14;
                if (i < m_lives) {
                    ink.Dot(x, 17, 4.5f);
                } else {
                    ink.Ring(x, 17, 4, 1.2f);
                }
            }
        }
    }
    void DrawDrop(const PetGameInk& ink, float x, float y) {
        ink.Color(PetGameRgb(89, 184, 255));
        ink.Place(x, y, 1, 1, 0);
        if (m_shapes.drop) {
            ink.target->FillGeometry(m_shapes.drop.get(), ink.brush);
        }
        ink.Home();
    }
    void DrawFruitPiece(const PetGameInk& ink, float x, float y, float spin) {
        ink.Place(x, y, 1, 1, std::sin(spin) * 0.3f);
        ink.Color(PetGameRgb(255, 138, 92));
        ink.Dot(-4, 0, 8);
        ink.Dot(4, 0, 8);
        if (m_shapes.stem) {
            ink.Color(PetGameRgb(79, 191, 108));
            ink.target->DrawGeometry(m_shapes.stem.get(), ink.brush, 2,
                                     m_shapes.roundCaps.get());
        }
        ink.Home();
    }
    // A rock, turning as it falls.
    void DrawRock(const PetGameInk& ink, float x, float y, float spin) {
        ink.Place(x, y, 1, 1, spin);
        if (m_shapes.rock) {
            ink.Color(PetGameRgb(125, 135, 140));
            ink.target->FillGeometry(m_shapes.rock.get(), ink.brush);
        }
        if (m_shapes.rockShine) {
            ink.Color(PetGameRgb(255, 255, 255, 0.15f));
            ink.target->FillGeometry(m_shapes.rockShine.get(), ink.brush);
        }
        ink.Home();
    }
    // A bolt, wobbling, over a bigger and fainter one (its glow).
    void DrawBolt(const PetGameInk& ink, float x, float y, double now) {
        const float wobble = (float)std::sin(now * 9) * 0.1f;
        if (m_shapes.bolt) {
            ink.Place(x, y, 1.5f, 1.5f, wobble);
            ink.Color(PetGameRgb(255, 211, 77), 0.22f);
            ink.target->FillGeometry(m_shapes.bolt.get(), ink.brush);
            ink.Place(x, y, 1, 1, wobble);
            ink.Color(PetGameRgb(255, 211, 77));
            ink.target->FillGeometry(m_shapes.bolt.get(), ink.brush);
        }
        ink.Home();
    }

    // ---- On the beat ----
    void InitRhythm(double now) {
        m_period = m_beatPeriod >= 0.3 && m_beatPeriod <= 1.2
                       ? m_beatPeriod
                       : 60 / kPetRhythmBpm;
        m_startAt = PetRhythmStart(now, m_beatPhase, m_beatPeriod);
        m_next = 0;
        m_judged.assign((size_t)kPetRhythmBeats, (char)0);
        m_score = 0;
        m_combo = 0;
        m_best = 0;
        m_hits = 0;
        m_messages.clear();
    }
    void Say(double now, const std::wstring& text, D2D1_COLOR_F color) {
        m_messages.push_back({now, text, color});
    }
    void StepRhythm(double now) {
        while (m_next < kPetRhythmBeats &&
               now > m_startAt + m_next * m_period + kPetRhythmGood) {
            if (!m_judged[m_next]) {
                m_judged[m_next] = 1;
                m_combo = 0;
                Say(now, Tr(L"missed", L"passou"),
                    PetGameRgb(255, 154, 154));
            }
            m_next++;
        }
        if (m_next >= kPetRhythmBeats &&
            now > m_startAt + kPetRhythmBeats * m_period) {
            Finish(now, m_score,
                   std::to_wstring(m_hits) + L"/" +
                       std::to_wstring(kPetRhythmBeats) + L" · " +
                       std::to_wstring(m_best) + L" " +
                       Tr(L"in a row", L"seguidos"));
        }
    }
    void ClickRhythm(double now) {
        int best = -1;
        double distance = 9;
        const int last = std::min(kPetRhythmBeats, m_next + 2);
        for (int k = std::max(0, m_next - 1); k < last; k++) {
            const double d = std::fabs(now - (m_startAt + k * m_period));
            if (!m_judged[k] && d < distance) {
                distance = d;
                best = k;
            }
        }
        const int judge = best < 0 ? 0 : PetRhythmJudge(distance);
        if (!judge) {
            m_combo = 0;
            Say(now, Tr(L"off the beat", L"fora do tempo"),
                PetGameRgb(255, 194, 75));
            return;
        }
        m_judged[best] = judge == 2 ? 3 : 2;
        m_combo++;
        m_hits++;
        m_best = std::max(m_best, m_combo);
        m_score += (judge == 2 ? 3 : 1) * (1 + m_combo / 8);
        Event(PetGameEvent::Happy);
        if (judge == 2) {
            Say(now, Tr(L"perfect", L"perfeito"), m_petColor);
        } else {
            Say(now, Tr(L"good", L"bom"), PetGameRgb(232, 237, 238));
        }
    }
    void DrawRhythm(const PetGameInk& ink,
                    const PetGameCanvas& canvas,
                    double now) {
        const float cx = m_w / 2, cy = m_h / 2 + 18, radius = 24;
        if (!m_ready) {
            DrawPet(canvas, cx, cy, 40, 0, 0, PetGamePose::Idle);
            return;
        }
        const bool playing = m_state == State::Playing;
        if (playing) {
            ink.Color(PetGameRgb(255, 255, 255, 0.18f));
            ink.Ring(cx, cy, radius, 2);
            for (int k = std::max(0, m_next - 1);
                 k < std::min(kPetRhythmBeats, m_next + 5); k++) {
                const double d = m_startAt + k * m_period - now;
                if (d < -0.15 || d > 1.7 || m_judged[k] >= 2) {
                    continue;
                }
                ink.Color(k % 4 == 0 ? m_petColor
                                     : PetGameRgb(232, 238, 240),
                          (float)(d < 0 ? std::max(0.0, 1 + d * 6)
                                        : 1 - d / 1.7 * 0.7));
                ink.Ring(cx, cy, radius + (float)std::max(0.0, d) * 105,
                         k % 4 == 0 ? 3.5f : 2.5f);
            }
        }
        double bob = 0;
        if (playing && now > m_startAt) {
            const double phase = (now - m_startAt) / m_period;
            bob = std::pow(1 - (phase - std::floor(phase)), 4) * 6;
        }
        DrawPet(canvas, cx, cy - (float)bob, 40, 0, 0, PetGamePose::Idle);
        if (!playing) {
            return;
        }
        if (now < m_startAt) {
            Text(ink, m_count.get(),
                 std::to_wstring((int)std::ceil((m_startAt - now) / 0.8)),
                 {12, cy - 86, m_w - 12, cy - 54}, PetGameRgb(242, 245, 246));
        }
        m_messages.erase(std::remove_if(m_messages.begin(), m_messages.end(),
                                        [now](const Message& m) {
                                            return now - m.at >= 0.8;
                                        }),
                         m_messages.end());
        for (const Message& message : m_messages) {
            const float e = (float)((now - message.at) / 0.8);
            const float y = cy - 52 - e * 24;
            Text(ink, m_message.get(), message.text,
                 {12, y - 12, m_w - 12, y + 12}, message.color, 1 - e);
        }
        DrawHud(ink, std::to_wstring(m_score), false);
        DrawHud(ink,
                m_combo > 1 ? std::to_wstring(m_combo) + L" " +
                                  Tr(L"in a row", L"seguidos")
                            : std::to_wstring(std::min(kPetRhythmBeats,
                                                       m_next)) +
                                  L"/" + std::to_wstring(kPetRhythmBeats),
                true);
    }

    // ---- Cloud jump ----
    void AddCloud() {
        const float height = (float)m_score;
        const float y = m_lastY - (52 + m_rng.Float() * 30 *
                                            std::min(1.7f, 1 + height / 120));
        const float r = m_rng.Float();
        const CloudKind kind = height > 60 && r < 0.2f    ? CloudKind::Fade
                               : height > 30 && r < 0.45f ? CloudKind::Move
                                                          : CloudKind::Fixed;
        m_clouds.push_back(
            {0.1f + m_rng.Float() * 0.8f, y, 66, m_rng.Float() * 6, 0, kind});
        m_lastY = y;
    }
    void InitClouds() {
        m_x = 0.5f;
        m_vx = 0;
        m_py = 0;
        m_vy = -kPetCloudJump;
        m_cam = -m_h + 70;
        m_score = 0;
        m_clouds.assign(1, Cloud{0.5f, 26, 90, 0, 0, CloudKind::Fixed});
        m_lastY = 26;
        while (m_lastY > m_cam - 120) {
            AddCloud();
        }
    }
    void StepClouds(double now, float dt) {
        Spring(m_x, m_vx, m_ptrX, 90, 14, dt);
        const float before = m_py;
        m_vy += kPetCloudGravity * dt;
        m_py += m_vy * dt;
        for (Cloud& cloud : m_clouds) {
            if (cloud.kind == CloudKind::Move) {
                cloud.x =
                    0.5f + (float)std::sin(now * 0.9 + cloud.phase) * 0.35f;
            }
            if (cloud.gone > 0) {
                cloud.gone += dt;
            }
            cloud.squish = std::max(0.0f, cloud.squish - dt * 4);
        }
        if (m_vy > 0) {
            for (Cloud& cloud : m_clouds) {
                if (cloud.gone > 0 ||
                    !PetCloudLands(before, m_py, cloud.y, m_x * m_w,
                                   cloud.x * m_w, cloud.w)) {
                    continue;
                }
                m_py = cloud.y - 10;
                m_vy = -kPetCloudJump;
                cloud.squish = 1;
                if (cloud.kind == CloudKind::Fade) {
                    cloud.gone = 0.001f;
                }
                Event(PetGameEvent::Happy);
                break;
            }
        }
        if (m_py - m_cam < m_h * 0.42f) {
            m_cam = m_py - m_h * 0.42f;
        }
        m_score = std::max(m_score, (int)std::lround(-m_py / 12));
        while (m_lastY > m_cam - 120) {
            AddCloud();
        }
        const float cam = m_cam, height = m_h;
        m_clouds.erase(std::remove_if(m_clouds.begin(), m_clouds.end(),
                                      [cam, height](const Cloud& c) {
                                          return c.y >= cam + height + 40 ||
                                                 c.gone >= 0.4f;
                                      }),
                       m_clouds.end());
        if (m_py - m_cam > m_h + 40) {
            Finish(now, m_score, L"");
        }
    }
    void DrawClouds(const PetGameInk& ink, const PetGameCanvas& canvas) {
        if (!m_ready) {
            DrawPet(canvas, m_w / 2, m_h - 50, 40, 0, -0.5f,
                    PetGamePose::Idle);
            return;
        }
        // Drawn opaque: the stage is flat, so a fading cloud is the color
        // mixed with it (overlapping parts of a cloud don't show).
        const D2D1_COLOR_F stage = PetGameRgb(7, 9, 11);
        for (const Cloud& cloud : m_clouds) {
            const float x = cloud.x * m_w, y = cloud.y - m_cam;
            const float fade = cloud.gone > 0 ? 1 - cloud.gone / 0.4f : 1;
            D2D1_COLOR_F color = cloud.kind == CloudKind::Fade
                                     ? PetGameRgb(150, 160, 166)
                                 : cloud.kind == CloudKind::Move
                                     ? PetGameRgb(220, 240, 255)
                                     : PetGameRgb(244, 247, 248);
            const float alpha =
                (cloud.kind == CloudKind::Fade ? 0.85f : 0.95f) * fade;
            color.r = stage.r + (color.r - stage.r) * alpha;
            color.g = stage.g + (color.g - stage.g) * alpha;
            color.b = stage.b + (color.b - stage.b) * alpha;
            ink.Color(color);
            // (Squashed where she landed: lower and wider, then back.)
            ink.Place(x, y + cloud.squish * 3, 1 + cloud.squish * 0.08f,
                      1 - cloud.squish * 0.15f, 0);
            ink.target->FillEllipse(
                D2D1_ELLIPSE{{0, 2}, cloud.w / 2, 7}, ink.brush);
            ink.Dot(-cloud.w * 0.18f, -2, 9);
            ink.Dot(cloud.w * 0.12f, -4, 11);
            ink.Home();
        }
        DrawPet(canvas, m_x * m_w, m_py - m_cam - 12, 34,
                std::clamp(m_vx * 0.6f, -1.0f, 1.0f), m_vy > 0 ? 0.7f : -0.6f,
                PetGamePose::Idle);
        if (m_state == State::Playing) {
            DrawHud(ink, std::to_wstring(m_score) + L" m", false);
        }
    }

    // ---- Island memory ----
    void InitMemory(double now) {
        int deck[kPetMemoryCards];
        for (int i = 0; i < kPetMemoryCards; i++) {
            deck[i] = i / 2;
        }
        for (int i = kPetMemoryCards - 1; i > 0; i--) {
            std::swap(deck[i], deck[m_rng.Next() % (i + 1)]);
        }
        for (int i = 0; i < kPetMemoryCards; i++) {
            m_cards[i] = {deck[i], 0, 0, false, -9,
                          now + i * kPetGameDealGap};
        }
        m_openCount = 0;
        m_moves = 0;
        m_pairs = 0;
        m_closeAt = 0;
        m_startAt = now;
    }
    // The cards turning, closing and popping; true while any moves.
    bool StepCards(double now, float dt) {
        if (m_closeAt > 0 && now >= m_closeAt) {
            for (int i = 0; i < m_openCount; i++) {
                m_cards[m_open[i]].target = 0;
            }
            m_openCount = 0;
            m_closeAt = 0;
        }
        bool moving = m_closeAt > 0;
        for (Card& card : m_cards) {
            if (AnimationLevel() >= 2) {
                card.up = card.target;
            } else {
                card.up += (card.target - card.up) * (1 - std::exp(-dt * 14));
                if (std::fabs(card.target - card.up) < 0.002f) {
                    card.up = card.target;
                }
            }
            moving |= card.up != card.target || now < card.pop + 0.35;
        }
        return moving;
    }
    void ClickMemory(float x, float y, double now) {
        if (m_closeAt > 0) {
            return;
        }
        const PetMemoryLayout layout = PetGameMemoryLayout(m_w, m_h);
        for (int i = 0; i < kPetMemoryCards; i++) {
            const float left =
                layout.left + (i % 4) * (layout.cardW + layout.gap);
            const float top =
                layout.top + (i / 4) * (layout.cardH + layout.gap);
            if (x < left || x >= left + layout.cardW || y < top ||
                y >= top + layout.cardH) {
                continue;
            }
            Card& card = m_cards[i];
            if (card.done || card.target > 0) {
                return;
            }
            card.target = 1;
            m_open[m_openCount++] = i;
            if (m_openCount == 2) {
                OpenedTwo(now);
            }
            return;
        }
    }
    // Two cards are up: a pair, or they close again in a moment.
    void OpenedTwo(double now) {
        m_moves++;
        Card& a = m_cards[m_open[0]];
        Card& b = m_cards[m_open[1]];
        if (a.icon != b.icon) {
            m_closeAt = now + 0.85;
            Event(PetGameEvent::Sad);
            return;
        }
        a.done = b.done = true;
        a.pop = b.pop = now + 0.25;
        m_pairs++;
        m_openCount = 0;
        Event(PetGameEvent::Love);
        if (m_pairs == kPetMemoryCards / 2) {
            Finish(now, std::llround((now - m_startAt) * 1000),
                   std::to_wstring(m_moves) + L" " + Tr(L"moves", L"jogadas"));
        }
    }
    // An icon in a unit square around the origin, as `placed` puts it.
    void DrawIcon(const PetGameInk& ink,
                  int icon,
                  const D2D1::Matrix3x2F& placed,
                  D2D1_COLOR_F color) {
        ink.target->SetTransform(placed);
        ink.Color(color);
        ID2D1StrokeStyle* caps = m_shapes.roundCaps.get();
        ID2D1RenderTarget* target = ink.target;
        switch (icon) {
            case 0:  // wifi
                if (m_shapes.wifi) {
                    target->DrawGeometry(m_shapes.wifi.get(), ink.brush, 0.11f,
                                         caps);
                }
                ink.Dot(0, 0.32f, 0.07f);
                break;
            case 1:  // sound
                if (m_shapes.speaker && m_shapes.waves) {
                    target->FillGeometry(m_shapes.speaker.get(), ink.brush);
                    target->DrawGeometry(m_shapes.waves.get(), ink.brush,
                                         0.11f, caps);
                }
                break;
            case 2:  // battery
                target->DrawRoundedRectangle(
                    D2D1_ROUNDED_RECT{{-0.4f, -0.2f, 0.32f, 0.2f}, 0.08f,
                                      0.08f},
                    ink.brush, 0.08f);
                target->FillRectangle({0.35f, -0.08f, 0.42f, 0.08f}, ink.brush);
                target->FillRectangle({-0.32f, -0.12f, 0.08f, 0.12f},
                                      ink.brush);
                break;
            case 3:  // note
                for (const D2D1_POINT_2F head :
                     {D2D1_POINT_2F{-0.14f, 0.24f},
                      D2D1_POINT_2F{0.24f, 0.14f}}) {
                    target->SetTransform(
                        D2D1::Matrix3x2F::Rotation(-0.4f * 180 / kPi, head) *
                        placed);
                    target->FillEllipse(D2D1_ELLIPSE{head, 0.13f, 0.1f},
                                        ink.brush);
                }
                target->SetTransform(placed);
                if (m_shapes.note) {
                    target->DrawGeometry(m_shapes.note.get(), ink.brush, 0.11f,
                                         caps);
                }
                break;
            case 4:  // bell
                if (m_shapes.bell) {
                    target->FillGeometry(m_shapes.bell.get(), ink.brush);
                }
                ink.Dot(0, 0.28f, 0.07f);
                break;
            default:  // moon
                ink.Dot(0, 0, 0.32f);
                ink.Color(PetGameRgb(0, 0, 0));
                ink.Dot(0.16f, -0.08f, 0.27f);
                break;
        }
    }
    void DrawMemory(const PetGameInk& ink,
                    const PetGameCanvas& canvas,
                    double now) {
        if (!m_ready) {
            DrawPet(canvas, m_w / 2, m_h / 2 + 30, 40, 0, 0, PetGamePose::Idle);
            return;
        }
        const PetMemoryLayout layout = PetGameMemoryLayout(m_w, m_h);
        const float w = layout.cardW, h = layout.cardH;
        const D2D1_COLOR_F mine = m_petColor;
        for (int i = 0; i < kPetMemoryCards; i++) {
            const Card& card = m_cards[i];
            // (Dealt one by one: each comes up from a little below,
            // fading in.)
            const double dealt =
                AnimationLevel() >= 2
                    ? 1.0
                    : PetEase((now - card.dealAt) / kPetGameDealSeconds);
            if (dealt <= 0) {
                continue;
            }
            ink.fade = (float)dealt;
            const float x = layout.left + (i % 4) * (w + layout.gap) + w / 2;
            const float y = layout.top + (i / 4) * (h + layout.gap) + h / 2 +
                            (1 - (float)dealt) * 20;
            const double sincePop = now - card.pop;
            const float pop =
                sincePop > 0 && sincePop < 0.35
                    ? (float)std::sin(sincePop / 0.35 * kPi) * 0.1f
                    : 0;
            const float sx =
                std::max(0.02f, std::fabs(std::cos(card.up * kPi))) *
                (1 + pop);
            ink.Place(x, y, sx, 1 + pop, 0);
            const D2D1_RECT_F rect{-w / 2, -h / 2, w / 2, h / 2};
            if (card.up < 0.5f) {
                ink.Color(PetGameRgb(21, 26, 29));
                ink.Card(rect, 12);
                ink.Color(mine, 0.55f);
                ink.Dot(0, 0, w * 0.08f);
                ink.Color(mine, 0.18f);
                ink.Ring(0, 0, w * 0.2f, 1);
            } else {
                ink.Color(PetGameRgb(0, 0, 0));
                ink.Card(rect, 12);
                if (card.done) {
                    ink.Color(mine, 0.9f);
                } else {
                    ink.Color(PetGameRgb(42, 49, 53));
                }
                ink.CardLine(rect, 12, 1.5f);
                D2D1_COLOR_F icon = PetGameRgb(242, 245, 246);
                if (card.done) {
                    icon = {mine.r + (1 - mine.r) * 0.3f,
                            mine.g + (1 - mine.g) * 0.3f,
                            mine.b + (1 - mine.b) * 0.3f, 1};
                }
                // (The icon is drawn in its own unit square.)
                const float size = w * 0.62f;
                DrawIcon(ink, card.icon,
                         ink.Matrix(x, y, sx * size, (1 + pop) * size, 0),
                         icon);
            }
            ink.Home();
        }
        ink.fade = 1;
        DrawPet(canvas, m_w - 30, 22, 26, 0, 0.4f, PetGamePose::Idle);
        if (m_state == State::Playing) {
            const int tenths = (int)((now - m_startAt) * 10);
            DrawHud(ink,
                    std::to_wstring(tenths / 10) + L"." +
                        std::to_wstring(tenths % 10) + L" s · " +
                        std::to_wstring(m_moves) + L" " +
                        Tr(L"moves", L"jogadas"),
                    false);
        }
    }

    // ---- Reflex ----
    void InitReflex(double now) {
        m_round = 0;
        m_times.clear();
        m_penalty = 0;
        m_reflex = ReflexState::Wait;
        m_at = now + 1.2 + m_rng.Float();
        m_lit = false;
        m_onTarget = false;
        m_decoys = 0;
        m_shake = -9;
        m_messageAt = -9;
        m_reflexMessage.clear();
    }
    void ReflexNext(double now) {
        m_reflex = ReflexState::Wait;
        m_lit = false;
        m_at = now + 0.5 + m_rng.Float() * 1.1;
    }
    void ReflexSay(double now, const std::wstring& text) {
        m_reflexMessage = text;
        m_messageAt = now;
    }
    // A color for the pill that is far from her color.
    D2D1_COLOR_F ReflexDecoy() {
        static const float kColors[8][3] = {
            {255, 93, 93},  {255, 194, 75}, {95, 224, 138}, {90, 169, 255},
            {169, 139, 255}, {255, 126, 182}, {238, 243, 245}, {63, 208, 201}};
        const float mine[3] = {m_petColor.r * 255, m_petColor.g * 255,
                               m_petColor.b * 255};
        int distant[8], count = 0, farthest = 0;
        float most = -1;
        for (int i = 0; i < 8; i++) {
            const float d = std::sqrt(std::pow(kColors[i][0] - mine[0], 2.0f) +
                                      std::pow(kColors[i][1] - mine[1], 2.0f) +
                                      std::pow(kColors[i][2] - mine[2], 2.0f));
            if (d > 140) {
                distant[count++] = i;
            }
            if (d > most) {
                most = d;
                farthest = i;
            }
        }
        const int pick = count ? distant[m_rng.Next() % count] : farthest;
        return PetGameRgb(kColors[pick][0], kColors[pick][1],
                          kColors[pick][2]);
    }
    void StepReflex(double now) {
        if (m_reflex == ReflexState::Wait && now >= m_at) {
            m_reflex = ReflexState::Lit;
            m_lit = true;
            if (m_decoys >= 3 || m_rng.Float() < 0.38f) {
                m_color = m_petColor;
                m_onTarget = true;
                m_shownAt = now;
                m_decoys = 0;
            } else {
                m_color = ReflexDecoy();
                m_onTarget = false;
                m_until = now + 0.55 + m_rng.Float() * 0.4;
                m_decoys++;
            }
        }
        if (m_reflex == ReflexState::Lit && m_onTarget &&
            now - m_shownAt > kPetReflexMissedMs / 1000.0) {
            m_times.push_back(kPetReflexMissedMs);
            ReflexSay(now, Tr(L"too slow", L"devagar demais"));
            m_round++;
            ReflexNext(now);
        }
        if (m_reflex == ReflexState::Lit && !m_onTarget && now > m_until) {
            ReflexNext(now);
        }
        if (m_round >= kPetReflexRounds) {
            Finish(now, PetReflexScore(m_times, m_penalty),
                   m_penalty ? Tr(L"Mistakes", L"Erros") + std::wstring(L": ") +
                                   std::to_wstring(m_penalty /
                                                   kPetReflexPenaltyMs)
                             : std::wstring(Tr(L"No mistakes", L"Sem erros")));
        }
    }
    void ClickReflex(double now) {
        if (m_reflex == ReflexState::Lit && m_onTarget) {
            const int ms = (int)std::lround((now - m_shownAt) * 1000);
            m_times.push_back(ms);
            ReflexSay(now, std::to_wstring(ms) + L" ms");
            m_round++;
            Event(PetGameEvent::Happy);
            ReflexNext(now);
        } else {
            m_penalty += kPetReflexPenaltyMs;
            m_shake = now;
            Event(PetGameEvent::Hurt);
            ReflexSay(now, Tr(L"not yet!", L"ainda não!"));
        }
    }
    void DrawReflex(const PetGameInk& ink,
                    const PetGameCanvas& canvas,
                    double now) {
        // (A wrong click shakes the whole stage, see Draw.)
        const float pw = std::min(m_w - 60, 360.0f), ph = 64;
        const float x = (m_w - pw) / 2, y = m_h / 2 - ph / 2 + 10;
        if (m_lit) {
            // (Kept in her paint for this target: made again only when the
            // color or the reach changes, see PetPaint.)
            const float reach = pw * 0.7f;
            uint64_t key = 0;
            const D2D1_COLOR_F color =
                PetAlpha(PetStepped(m_color, &key), 0.35f);
            key |= (uint64_t)std::lround(reach) << 20;
            const D2D1_GRADIENT_STOP stops[] = {
                {0, color}, {10 / reach, color}, {1, PetAlpha(color, 0)}};
            PetPaint* paint = PetPaintFor(ink.target);
            ID2D1RadialGradientBrush* glow =
                paint ? PetGradient(*paint, paint->reflex, paint->reflexKey,
                                    key, stops, 3)
                      : nullptr;
            if (glow) {
                glow->SetCenter({m_w / 2, y + ph / 2});
                glow->SetRadiusX(reach);
                glow->SetRadiusY(reach);
                ink.target->FillRectangle({0, 0, m_w, m_h}, glow);
            }
        }
        const D2D1_RECT_F pill{x, y, x + pw, y + ph};
        ink.Color(m_lit ? m_color : PetGameRgb(0, 0, 0));
        ink.Card(pill, ph / 2);
        ink.Color(PetGameRgb(42, 49, 53));
        ink.CardLine(pill, ph / 2, 1);
        DrawPet(canvas, x + ph / 2 + 4, y + ph / 2, 44, 0.6f, 0,
                m_state == State::Playing && m_reflex == ReflexState::Wait
                    ? PetGamePose::Focus
                    : PetGamePose::Idle);
        if (m_state != State::Playing || !m_ready) {
            return;
        }
        ink.Color(m_petColor);
        ink.Dot(m_w / 2, y + ph + 22, 7);
        Text(ink, m_line.get(),
             Tr(L"click when the pill turns this color",
                L"clique quando a pílula ficar desta cor"),
             {12, y + ph + 34, m_w - 12, y + ph + 56},
             PetGameRgb(147, 160, 166));
        const float since2 = (float)(now - m_messageAt);
        if (since2 < 1) {
            const float my = y - 26 - since2 * 10;
            Text(ink, m_message.get(), m_reflexMessage,
                 {12, my - 12, m_w - 12, my + 12}, PetGameRgb(242, 245, 246),
                 1 - since2);
        }
        DrawHud(ink,
                Tr(L"Round", L"Rodada") + std::wstring(L" ") +
                    std::to_wstring(std::min(kPetReflexRounds, m_round + 1)) +
                    L"/" + std::to_wstring(kPetReflexRounds),
                false);
    }

    // ---- Drawing helpers ----
    static winrt::com_ptr<IDWriteTextFormat> MakeFormat(
        IDWriteFactory* dwrite,
        PCWSTR family,
        DWRITE_FONT_WEIGHT weight,
        float size,
        DWRITE_TEXT_ALIGNMENT alignment) {
        winrt::com_ptr<IDWriteTextFormat> format;
        const PCWSTR font = UiFont(family);
        if (SUCCEEDED(dwrite->CreateTextFormat(
                font, nullptr, weight, DWRITE_FONT_STYLE_NORMAL,
                UiStretch(font), size, L"", format.put()))) {
            format->SetTextAlignment(alignment);
            format->SetParagraphAlignment(DWRITE_PARAGRAPH_ALIGNMENT_CENTER);
            format->SetWordWrapping(DWRITE_WORD_WRAPPING_NO_WRAP);
            // Too long texts end with "...".
            const DWRITE_TRIMMING trimming{
                DWRITE_TRIMMING_GRANULARITY_CHARACTER, 0, 0};
            winrt::com_ptr<IDWriteInlineObject> ellipsis;
            dwrite->CreateEllipsisTrimmingSign(format.get(), ellipsis.put());
            format->SetTrimming(&trimming, ellipsis.get());
        }
        return format;
    }
    winrt::com_ptr<IDWriteTextFormat> Format(PCWSTR family,
                                             DWRITE_FONT_WEIGHT weight,
                                             float size,
                                             DWRITE_TEXT_ALIGNMENT alignment) {
        return MakeFormat(m_dwrite.get(), family, weight, size, alignment);
    }
    static void Text(const PetGameInk& ink,
                     IDWriteTextFormat* format,
                     const std::wstring& text,
                     const D2D1_RECT_F& rect,
                     D2D1_COLOR_F color,
                     float alpha = 1) {
        if (!format || text.empty()) {
            return;
        }
        ink.Color(color, alpha);
        ink.target->DrawText(text.c_str(), (UINT32)text.size(), format, rect,
                             ink.brush);
    }
    // The score or clock in a top corner.
    void DrawHud(const PetGameInk& ink, const std::wstring& text, bool right) {
        Text(ink, right ? m_hudRight.get() : m_hudLeft.get(), text,
             {12, 6, m_w - 12, 28}, PetGameRgb(232, 236, 237));
    }
    void DrawPet(const PetGameCanvas& canvas,
                 float x,
                 float y,
                 float h,
                 float lookX,
                 float lookY,
                 PetGamePose pose) {
        if (canvas.drawPet) {
            canvas.drawPet(canvas.host, canvas.target, {x, y}, h, lookX, lookY,
                           pose);
        }
    }
    // The title screen, and the end of a round: they come in (the name
    // springs up, the line under it follows) and go when a round starts.
    void DrawScreens(const PetGameInk& ink, double now) {
        const bool still = AnimationLevel() >= 2;
        State screen = m_state;
        // How much of it is there: coming in (0 to 1), or going (1 to 0).
        float arrival = 1;
        float away = 1;
        double since = 1;
        if (m_state == State::Playing) {
            const float gone =
                (float)((now - m_startedAt) / kPetGameAwaySeconds);
            if (still || m_screenWas == State::Playing || gone >= 1) {
                return;
            }
            screen = m_screenWas;
            away = 1 - gone;
        } else {
            const double at = m_state == State::Title ? m_titleAt : m_overAt;
            if (!still && at > 0) {
                since = now - at;
                arrival = (float)std::clamp(since / kPetGameScreenSeconds, 0.0,
                                            1.0);
            }
        }
        const float shown = away * arrival;
        // (The name springs from smaller, past its size and back; the line
        // under it follows a moment later.)
        const float spring =
            away < 1 ? 1
                     : 1 - std::exp(-arrival * 6.0f) *
                               std::cos(arrival * 9.0f) * 0.4f;
        const float under =
            away < 1 || still
                ? 1.0f
                : (float)std::clamp((since - 0.15) / 0.3, 0.0, 1.0);
        const float top = std::max(8.0f, m_h / 2 - 78);
        const D2D1_COLOR_F white = PetGameRgb(242, 245, 246);
        const D2D1_COLOR_F grey = PetGameRgb(147, 160, 166);
        const auto name = [&](const std::wstring& text) {
            ink.Place(m_w / 2, top + 13, spring, spring, 0);
            Text(ink, m_title.get(), text,
                 {12 - m_w / 2, -13, m_w / 2 - 12, 13}, white, shown);
            ink.Home();
        };
        if (screen == State::Title) {
            ink.Color(PetGameRgb(4, 6, 7, 0.4f), shown);
            ink.target->FillRectangle({0, 0, m_w, m_h}, ink.brush);
            name(PetGameName(m_id));
            Text(ink, m_line.get(), Tr(L"Click to play", L"Clique para jogar"),
                 {12, top + 28, m_w - 12, top + 50}, grey, shown * under);
            return;
        }
        ink.Color(PetGameRgb(7, 9, 11, 0.55f), shown);
        ink.target->FillRectangle({0, 0, m_w, m_h}, ink.brush);
        const std::wstring value =
            PetGameFormatValue(m_id, m_finalRecord.value);
        name(std::wstring(m_newRecord ? Tr(L"New record", L"Novo recorde")
                                      : Tr(L"Game over", L"Fim")) +
             L": " + value);
        float y = top + 28;
        if (!m_finalRecord.extra.empty()) {
            Text(ink, m_line.get(), m_finalRecord.extra,
                 {12, y, m_w - 12, y + 22}, white, shown * under);
            y += 22;
        }
        Text(ink, m_line.get(),
             Tr(L"Click to play again", L"Clique para jogar de novo"),
             {12, y, m_w - 12, y + 22}, grey, shown * under);
    }

    // The texts' fonts (the island's), made by Prepare.
    winrt::com_ptr<IDWriteFactory> m_dwrite;
    size_t m_fonts = 0;
    winrt::com_ptr<IDWriteTextFormat> m_hudLeft, m_hudRight, m_title, m_line,
        m_message, m_count;
    PetGameShapes m_shapes;
};

////////////////////////////////////////////////////////////////////////////////
// Faísca's care and her panel (petpanel). Her care (islandPetCare): energy,
// food, water, love and fun (only with her games on), from 0 to 100. One pet
// for the PC: the values are shared by every island and profile; each
// profile only chooses whether she is looked after there, and how fast she
// asks. They go down only while
// some island looks after her, the session is unlocked and the PC is awake
// (see PetCareClock, Island::UpdateCareWatch), never under kPetCareFloor
// (she never goes away), and under kPetCareLow she asks (PetCareNeedOf).
enum PetCareKind {
    kPetEnergy,
    kPetFood,
    kPetWater,
    kPetLove,
    kPetFun,
    kPetCares
};
using PetCareValues = std::array<float, kPetCares>;
constexpr float kPetCareFull = 100;
constexpr float kPetCareLow = 25;
constexpr float kPetCareFloor = 5;
// The paces (islandPetCarePace: calm, normal, attentive): hours of use
// from full to kPetCareLow for her food; the others go this much slower or
// faster (energy, food, water, love, fun: at the normal pace from full to
// the floor in about 8 hours, bored after about 6).
constexpr int kPetCarePaces = 3;
constexpr double kPetCareHours[kPetCarePaces] = {24, 8, 3};
constexpr double kPetCareShare[kPetCares] = {0.5, 1, 1.2, 0.85, 1.25};
// What looking after her gives: an action (and energy with it), a second
// of petting, a fruit or a drop caught in a game, a round played.
constexpr float kPetCareGift = 30;
constexpr float kPetCareGiftEnergy = 6;
constexpr float kPetCarePetting = 2.5f;
constexpr float kPetCareBite = 4;
constexpr float kPetCarePlayed = 6;
// Her fun (with her games on): moping under kPetFunMoping (bored under
// kPetCareLow); what a round of a game gives (more for a longer round and a
// good result, see PetFunForRound), a second of petting, a tap, a second of
// dancing to music.
constexpr float kPetFunMoping = 12;
constexpr float kPetFunRound = 18;
constexpr float kPetFunLong = 14;
constexpr float kPetFunGood = 10;
constexpr float kPetFunRoundMost = 40;
constexpr float kPetFunPetting = 0.5f;
constexpr float kPetFunTap = 1.5f;
constexpr float kPetFunDance = 0.002f;
// Kept this often at most while she's seen, and at once on what matters
// (an action, her panel closing, the session locked, the island going).
constexpr double kPetCareSaveSeconds = 600;
// Where it's kept: the values (see PetCareEncode), her first day (a day
// number, see PetDay) and her games' records (see PetGames).
constexpr WCHAR kPetCareKey[] = L"petCare";
constexpr WCHAR kPetSinceKey[] = L"petSince";
constexpr WCHAR kPetRecordsKey[] = L"petGameRecords";

// `values` after `seconds` of care at `pace`.
PetCareValues PetCareDecay(PetCareValues values, double seconds, int pace) {
    const double perSecond =
        (kPetCareFull - kPetCareLow) /
        (kPetCareHours[std::clamp(pace, 0, kPetCarePaces - 1)] * 3600);
    for (int i = 0; i < kPetCares; i++) {
        const float drop =
            (float)(perSecond * kPetCareShare[i] * std::max(seconds, 0.0));
        values[i] =
            std::max(std::min(values[i], kPetCareFloor), values[i] - drop);
    }
    return values;
}

// "PC2|1000|820|640|990|700": the values in tenths (energy, food, water,
// love, fun).
std::wstring PetCareEncode(const PetCareValues& values) {
    std::wstring text = L"PC2";
    for (float value : values) {
        text += L'|';
        text += std::to_wstring(
            std::lround(std::clamp(value, 0.0f, kPetCareFull) * 10));
    }
    return text;
}

// False (and `out` left as it is) for anything else. Kept before her fun
// ("PC1", four values): her fun starts full.
bool PetCareDecode(const std::wstring& text, PetCareValues* out) {
    const bool before = text.starts_with(L"PC1|");
    if (!before && !text.starts_with(L"PC2|")) {
        return false;
    }
    const int count = before ? kPetFun : kPetCares;
    PetCareValues values{};
    values[kPetFun] = kPetCareFull;
    size_t at = 4;
    for (int i = 0; i < count; i++) {
        const size_t end = text.find(L'|', at);
        if ((end == std::wstring::npos) != (i == count - 1)) {
            return false;
        }
        const size_t length =
            end == std::wstring::npos ? text.size() - at : end - at;
        if (length < 1 || length > 4) {
            return false;
        }
        int tenths = 0;
        for (size_t k = at; k < at + length; k++) {
            if (text[k] < L'0' || text[k] > L'9') {
                return false;
            }
            tenths = tenths * 10 + (text[k] - L'0');
        }
        if (tenths > 1000) {
            return false;
        }
        values[i] = tenths / 10.0f;
        at = end + 1;
    }
    *out = values;
    return true;
}

// What she asks for: the lowest of food, water and love under kPetCareLow;
// else, with her fun looked after (`fun`: her games on), bored under it and
// moping under kPetFunMoping. (Energy never asks.)
PetNeed PetCareNeedOf(const PetCareValues& values, bool fun = false) {
    int lowest = -1;
    for (int kind : {kPetFood, kPetWater, kPetLove}) {
        if (values[kind] < kPetCareLow &&
            (lowest < 0 || values[kind] < values[lowest])) {
            lowest = kind;
        }
    }
    if (lowest < 0 && fun && values[kPetFun] < kPetCareLow) {
        return values[kPetFun] < kPetFunMoping ? PetNeed::Moping
                                               : PetNeed::Bored;
    }
    return lowest == kPetFood    ? PetNeed::Hungry
           : lowest == kPetWater ? PetNeed::Thirsty
           : lowest == kPetLove  ? PetNeed::Lonely
                                 : PetNeed::None;
}

// The fun a round of her games gives: more the longer it lasted (`seconds`,
// up to a minute counts) and for a good result, up to kPetFunRoundMost.
float PetFunForRound(double seconds, bool good) {
    return std::min(kPetFunRoundMost,
                    kPetFunRound +
                        kPetFunLong * (float)(std::clamp(seconds, 0.0, 60.0) /
                                              60) +
                        (good ? kPetFunGood : 0.0f));
}

// The hours of PC use her fun took to go down to `fun` at `pace` (her
// reason in her panel: "nobody has played with her for 6 h"), 1 at least.
int PetFunIdleHours(float fun, int pace) {
    const double perHour =
        (kPetCareFull - kPetCareLow) /
        kPetCareHours[std::clamp(pace, 0, kPetCarePaces - 1)] *
        kPetCareShare[kPetFun];
    return std::max(
        1, (int)std::lround(std::max(0.0f, kPetCareFull - fun) / perHour));
}

// A day's number (days since 1601), for "together for N days".
int PetDay(const SYSTEMTIME& local) {
    SYSTEMTIME day = local;
    day.wHour = day.wMinute = day.wSecond = day.wMilliseconds = 0;
    FILETIME file;
    if (!SystemTimeToFileTime(&day, &file)) {
        return 0;
    }
    const ULONGLONG ticks =
        ((ULONGLONG)file.dwHighDateTime << 32) | file.dwLowDateTime;
    return (int)(ticks / 864000000000ULL);
}

int PetToday() {
    SYSTEMTIME now;
    GetLocalTime(&now);
    return PetDay(now);
}

// Since her first day (`since`, 0 unknown) to `today`.
std::wstring PetTogetherText(int since, int today) {
    const int days = since > 0 ? std::max(0, today - since) : 0;
    if (days == 0) {
        return Tr(L"Together since today", L"Juntas desde hoje");
    }
    if (days == 1) {
        return Tr(L"Together for 1 day", L"Juntas há 1 dia");
    }
    return FilledText(Tr(L"Together for %s days", L"Juntas há %s dias"),
                      {std::to_wstring(days)});
}

// Her care as it is: the values when last settled (`at`, on
// PetCareClock), when last kept, the pace, read from where it's kept
// (once), looked after now (by some island) and paused (the session
// locked).
struct PetCareState {
    PetCareValues values{kPetCareFull, kPetCareFull, kPetCareFull,
                         kPetCareFull, kPetCareFull};
    double at = 0;
    double savedAt = 0;
    int pace = 0;
    bool loaded = false;
    bool running = false;
    bool paused = false;
    // Her fun looked after too (some island has her games on): without, it
    // stays as it is.
    bool fun = false;
};
PetCareState g_petCare;

// Seconds the PC has been awake (its sleep and hibernation don't count).
double PetCareClock() {
    ULONGLONG time = 0;
    QueryUnbiasedInterruptTime(&time);
    return time / 1e7;
}

// The values now: gone down since they were settled, while looked after.
PetCareValues PetCareNow() {
    if (!g_petCare.running || g_petCare.paused) {
        return g_petCare.values;
    }
    PetCareValues values = PetCareDecay(
        g_petCare.values, PetCareClock() - g_petCare.at, g_petCare.pace);
    if (!g_petCare.fun) {
        values[kPetFun] = g_petCare.values[kPetFun];
    }
    return values;
}

void PetCareSettle() {
    g_petCare.values = PetCareNow();
    g_petCare.at = PetCareClock();
}

void PetCareLoad() {
    if (!g_petCare.loaded) {
        g_petCare.loaded = true;
        PetCareDecode(GetStringValueIn(kPetCareKey, 64), &g_petCare.values);
    }
}

// Kept (settled first), while she's looked after.
void PetCareSave() {
    if (!g_petCare.running) {
        return;
    }
    PetCareSettle();
    Wh_SetStringValue(kPetCareKey, PetCareEncode(g_petCare.values).c_str());
    g_petCare.savedAt = PetCareClock();
}

// Given some (an action, petting, a game), up to full; kept later.
void PetCareGive(int kind, float amount) {
    if (!g_petCare.running) {
        return;
    }
    PetCareSettle();
    g_petCare.values[kind] =
        std::min(kPetCareFull, g_petCare.values[kind] + amount);
}

// The session's lock and unlock told to `window` (WM_WTSSESSION_CHANGE),
// or not any more; wtsapi32 loaded the first time it's needed.
bool WatchSessionLock(HWND window, bool on) {
    using Register_t = BOOL(WINAPI*)(HWND, DWORD);
    using Unregister_t = BOOL(WINAPI*)(HWND);
    static const HMODULE wts = LoadLibraryEx(L"wtsapi32.dll", nullptr,
                                             LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!wts) {
        return false;
    }
    if (on) {
        auto watch = (Register_t)GetProcAddress(
            wts, "WTSRegisterSessionNotification");
        // (NOTIFY_FOR_THIS_SESSION.)
        return watch && watch(window, 0);
    }
    auto unwatch =
        (Unregister_t)GetProcAddress(wts, "WTSUnRegisterSessionNotification");
    return unwatch && unwatch(window);
}

