// The pool for a mood (asleep with Do not disturb on, it says why).
PetLineKey PetLineKeyOfMood(PetMood mood, bool quiet) {
    switch (mood) {
        case PetMood::Music:
            return PetLineKey::Music;
        case PetMood::Notify:
            return PetLineKey::Notify;
        case PetMood::Focus:
            return PetLineKey::Focus;
        case PetMood::Cpu:
            return PetLineKey::Cpu;
        case PetMood::Ram:
            return PetLineKey::Ram;
        case PetMood::Gpu:
            return PetLineKey::Gpu;
        case PetMood::Tired:
            return PetLineKey::Tired;
        case PetMood::Sleep:
            return quiet ? PetLineKey::SleepQuiet : PetLineKey::Sleep;
        case PetMood::Hungry:
            return PetLineKey::Hungry;
        case PetMood::Thirsty:
            return PetLineKey::Thirsty;
        case PetMood::Lonely:
            return PetLineKey::Lonely;
        case PetMood::Holding:
            return PetLineKey::Holding;
        case PetMood::Bored:
            return PetLineKey::Bored;
        case PetMood::Moping:
            return PetLineKey::Moping;
        default:
            return PetLineKey::Idle;
    }
}

