    // What was told last (see SetAppBarPosition).
    UINT m_appBarEdge = ABE_TOP;
    int m_appBarThickness = -1;
    RECT m_appBarMonitor{};
    // The strip kept, as the system gave it.
    RECT m_appBarRect{};
