    std::wstring m_petSongApp;
    int m_petSongSource = -1;
    // Reacting to the PC's use while it's seen (islandPetReacts): the usage
    // thread runs for it too (see UpdateUsageWatch, OnUsage).
    bool PetReactsNow() const {
        return m_petTimerOn && g_settings.islandPet &&
               g_settings.islandPetReacts;
    }
