    IDWriteTextFormat* m_compactTitleFormat = nullptr;
    float m_compactTitleLine = 0;
    float m_compactTitleWidth = 0;
    // The text on one line that scrolls, not opening on more lines (with
    // animations reduced, only those lines can show all of it).
    bool BannerTextScrolls() const {
        return g_settings.islandBannerMarquee && AnimationLevel() == 0;
    }
    // How far it scrolls (as last drawn): its place goes in the render key.
    float m_mediaMarqueeDistance = 0;
    bool MediaTitleScrolls() const {
        return g_settings.islandMediaMarquee && m_mediaShown.playing &&
               !m_away && AnimationLevel() == 0 &&
               m_mediaTitleFullWidth > m_mediaTitleWidth + 1;
    }
