// A card's source icon clicked: the island's own sound (0), the pack (1:
// downloaded the first time, again after a failed download) or a file of
// yours (2: the file picker, also to pick another one).
void ControlPanel::SetPetSoundSource(int sound, int choice) {
    PetSoundList sounds = CurrentPetSounds();
    PetSoundSlot& slot = sounds[sound];
    m_petSoundNote.clear();
    if (choice == 2) {
        StartPetSoundFileDialog(sound);
        return;
    }
    const int next = choice == 1 && kPetSoundPackCount ? kPetSourcePack
                                                       : kPetSourceNative;
    if (next >= kPetSourcePack) {
        const PetPackState state =
            PetSoundPackStatus(next - kPetSourcePack).state;
        if (slot.source == next && state != PetPackState::Failed) {
            PetPreviewSound((PetSound)sound);
            return;
        }
        RequestPetSoundPack(next - kPetSourcePack);
    }
    slot.source = next;
    slot.path.clear();
    SetPetSoundList(EncodePetSoundList(sounds));
    PetPreviewSound((PetSound)sound);
    Layout();
}

