// What finds the pill's separator lines (the order strip's "+ Line" chip), in
// every language of the island.
std::wstring SeparatorSearchWords() {
    return L" separator separators line lines divider Separador "
           L"separadores linha linhas divisor 分隔线 分割线 分隔 "
           L"Trennlinie Trenner Linie línea líneas Разделитель "
           L"разделительная линия 区切り線 区切り 線 đường kẻ phân cách "
           L"vạch ngăn";
}

// A search that is about them: long enough not to find them with any
// letter (two Chinese or Japanese characters are enough).
bool SeparatorSearch(const std::wstring& query) {
    size_t letters = 0;
    bool wide = false;
    for (const WCHAR c : query) {
        if (c != L' ') {
            letters++;
            wide = wide || c >= 0x2E80;
        }
    }
    return letters >= (wide ? 2u : 3u) &&
           MatchesSearch(SeparatorSearchWords(), query);
}

