        case IslandPref::MediaTotalTime:
            return needsEither(IslandPref::Media, IslandPref::MediaTitle);
        case IslandPref::NoticeCharger:
            return needs(IslandPref::StatusNotices);
        case IslandPref::NoticeLowBattery:
            return needs(IslandPref::StatusNotices);
        case IslandPref::NoticeBluetooth:
            return needs(IslandPref::StatusNotices);
        case IslandPref::NoticeBluetoothLow:
