            return needs(IslandPref::Pet);
        case IslandPref::PetReactAll:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactNotify:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactFiles:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactDownload:
