        case IslandPref::PetReactVolume:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactUsb:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactCharger:
            return needs(IslandPref::PetReacts);
        case IslandPref::PetReactWifiDown:
