// The pill's media buttons' size or the media panel's (%), kept in the
// profile: the pill laid out again as the buttons' slider moves; the open
// panel at its new size once the panel's is let go (like SetPanelSize).
void SetMediaBigSize(int slider, int percent, bool keep) {
    percent = std::clamp(percent, kMediaBigMin, kMediaBigMax);
    const bool buttons = slider == kSliderMediaButtons;
    if (keep) {
        StoreProfileInt(buttons ? L"islandMediaButtonsSize"
                                : L"islandMediaPanelSize",
                        percent);
    }
    int& setting = buttons ? g_settings.islandMediaButtonsSize
                           : g_settings.islandMediaPanelSize;
    if (percent == setting && !(keep && !buttons)) {
        return;
    }
    setting = percent;
    if (!g_island || g_applyingProfile) {
        return;
    }
    if (buttons) {
        ForEachIsland([](Island& island) { island.OnPreferencesChanged(); });
    } else if (keep) {
        ForEachIsland([](Island& island) { island.RescalePanels(); });
    }
}

